insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'standing', array['먼저 내 그립을 잡고 상대 그립은 끊는다','상대 자세를 무너뜨린 뒤 넘기거나 가드로 내려간다','넘어가도 다치지 않게 낙법으로 받는다']::text[], array['오른발 반 보 앞, 무릎 굽히고 엉덩이는 어깨 밑에 둔다','내 오른손 상대 왼쪽 깃 · 내 왼손 상대 오른쪽 소매','머리는 들고 턱은 당긴다 — 머리가 숙여지면 바로 세운다','상대에게 기대지 않는다 — 내 체중은 내 두 발 위']::text[], array['상대가 상체를 숙이고 다가오면 → 스프롤 (테이크다운 방어)','상대 오른다리가 앞에 나와 있으면 → 싱글 레그 테이크다운 또는 앵클 픽','상대가 뒤로 버티며 팔을 뻗으면 → 레벨 체인지 테이크다운','상대가 앞으로 밀고 들어오면 → 업어치기 또는 허리후리기','상대 체중이 오른발 뒤꿈치에 실리면 → 밭다리후리기 또는 안다리후리기']::text[], array['허리를 숙여 머리만 내밀면 앞으로 끌려 넘어진다 → 무릎을 굽혀 낮아지고 상체는 세운다','그립을 오래 잡힌 채 두면 상대가 원하는 던지기를 고른다 → 잡히면 바로 끊고 다시 잡는다','두 발을 나란히 모으면 앞뒤로 쉽게 쓸린다 → 오른발 반 보 앞을 지킨다']::text[], array['그립 싸움만 1분 — 잡고 끊고 다시 잡기를 번갈아 한다','혼자 낙법 · 레벨 체인지 스텝 10회씩']::text[] from public.positions where slug = 'standing' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'standing', array['언더훅 · 머리 위치를 먼저 차지한다','상대 등 뒤로 돌거나 넘기고, 불리하면 가드를 잡고 내려간다','뒤를 잡히면 떼고 돌아서 다시 마주 본다']::text[], array['내 오른팔 상대 왼팔 밑 언더훅, 머리는 상대 턱 왼쪽에 붙인다','엉덩이는 뒤로 빼지 말고 상대 골반 가까이 둔다','칼라 타이는 내 오른손 상대 목 뒤, 내 왼손 상대 오른쪽 손목','가드를 잡을 땐 그립 먼저 잡고 엉덩이부터 바닥에 내린다']::text[], array['상대가 언더훅을 넣으려 하면 → 언더훅 퍼멀링','상대 머리가 숙여지면 → 스냅 다운 또는 길로틴 초크 (스탠딩)','상대 오른팔이 뻗어 나오면 → 암 드래그 (스탠딩) 또는 러시안 타이 → 백 테이크','서서 싸우기 불리하면 → 가드 풀링 또는 앉아서 가드 잡기 (시팅 가드)','뒤에서 허리를 잡히면 → 바디락 빠져나오기 또는 스탠딩 스위치']::text[], array['가드를 잡으며 그냥 주저앉으면 상대가 바로 패스한다 → 그립을 먼저 잡고 발을 골반에 댄다','언더훅을 내준 채 버티면 뒤를 잡힌다 → 팔을 다시 밀어 넣거나 클린치를 끊는다','뒤를 잡히고 손을 놓고 서 있으면 들려 던져진다 → 상대 손부터 떼고 무게를 낮춘다']::text[], array['언더훅 퍼멀링 2분 — 서로 번갈아 팔을 밀어 넣는다','그립 잡고 가드 풀링 · 다시 일어서기 10회']::text[] from public.positions where slug = 'clinch' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['자세를 세워 팔과 목을 지킨다','상대 그립을 끊고 다리 잠금을 연다','가드가 열리면 바로 패스로 넘어간다']::text[], array['등은 펴고 머리는 엉덩이 위 — 머리가 앞으로 쏠리면 바로 세운다','두 손은 상대 배 · 골반이나 허리띠에, 매트를 짚지 않는다','무릎은 넓게 벌려 좌우 스윕을 막는다','두 팔을 같이 넣거나 같이 빼 한 팔만 안에 남기지 않는다']::text[], array['상대가 내 목 · 깃을 당겨 자세가 무너지면 → 클로즈드 가드 안 자세 되찾기','자세가 섰고 손이 골반에 있으면 → 가드 열기 (무릎 쐐기) 또는 스탠딩 가드 브레이크','상대가 내 오른팔을 오버훅으로 감으면 → 위저 (오버훅으로 막기) 또는 오버훅 가드 풀기','가드가 열리면 → 니슬라이스 (클로즈드 가드 열고) 또는 스택 패스 (클로즈드 가드)','상대가 다리를 올려 트라이앵글 · 암바를 노리면 → 스택 당했을 때 방어 (가드)']::text[], array['손을 매트에 짚으면 팔을 잡혀 스윕 · 암바가 온다 → 손은 상대 몸 위에 둔다','자세 없이 바로 패스하려 하면 트라이앵글에 걸린다 → 자세 · 그립 · 열기 · 패스 순서로 간다','무릎을 모으면 옆으로 쉽게 쓸린다 → 무릎을 넓게 벌린다']::text[], array['파트너가 목을 당기면 자세 되찾기 1분 반복','무릎 쐐기로 가드 열기 · 다시 닫히기 10회']::text[] from public.positions where slug = 'closed-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['상대 자세를 무너뜨려 팔과 머리를 끌어온다','각도를 만들어 스윕이나 서브미션을 건다','상대가 일어서거나 열면 다른 가드로 이어 간다']::text[], array['내 왼손 상대 오른쪽 소매(손목), 내 오른손 상대 목 뒤 · 깃','다리로 허리를 당겨 상대 자세를 계속 깬다','등만 대고 누워 있지 말고 엉덩이를 좌우로 빼 각도를 만든다','한 공격을 막으면 막은 팔 쪽 다음 공격으로 잇는다']::text[], array['상대가 자세를 세우고 버티면 → 클로즈드 가드 (자세 · 포스처 깨기) 또는 힙 범프 스윕','상대 오른팔이 내 가슴 앞에 남아 있으면 → 클로즈드 가드 암바 또는 트라이앵글 초크','상대가 한 팔을 안에 넣고 한 팔을 빼면 → 트라이앵글 초크','상대가 내 몸을 짚고 팔을 뻗으면 → 기무라 (가드) 또는 기무라 스윕','상대가 일어서면 → 상대가 섰을 때 클로즈드 가드 유지 또는 100% 스윕 (상대가 섰을 때 다리 안아 넘기기)']::text[], array['그립 없이 다리만 잠그고 누워 있으면 상대가 편하게 연다 → 소매 · 깃부터 잡고 자세를 깬다','정면으로만 누워 공격하면 막힌다 → 엉덩이를 빼 각도를 먼저 만든다','한 기술만 계속 시도하면 읽힌다 → 암바 · 트라이앵글 · 스윕을 이어서 건다']::text[], array['자세 깨기 → 시저 스윕 연결 10회','힙 범프 → 기무라 → 길로틴 연결 반복']::text[] from public.positions where slug = 'closed-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['상대 다리 · 발을 먼저 잡아 가드를 무력화한다','옆으로 각도를 만들어 다리를 지나간다','패스 후 바로 눌러 가드 회복을 막는다']::text[], array['엉덩이는 뒤로, 상체는 세워 앞으로 끌려가지 않는다','손은 상대 무릎 · 바지 · 발목을 잡고 상대 그립은 바로 끊는다','정면에 서 있지 말고 좌우로 움직여 각도를 만든다','상대 가드 종류를 먼저 보고 붙을지 떨어질지 정한다']::text[], array['상대가 두 발을 내 골반에 대고 밀면 → 발 골반 가드 패스','상대 정강이가 내 정강이 안쪽에 붙으면 → 신 투 신 가드 패스','상대가 케이 가드로 다리를 노리면 → 케이 가드 패스','상대가 앉아서 발목을 노리면 → 토레안도 패스 또는 롱 스텝 패스']::text[], array['상체를 숙이고 다가가면 칼라 드래그 · 스윕을 당한다 → 엉덩이를 빼고 상체를 세운다','그립을 내준 채 패스하려 하면 계속 밀려난다 → 그립부터 끊고 내 그립을 잡는다','늘 상대 오른쪽으로만 패스하면 읽힌다 → 상대 왼쪽을 보여 주고 오른쪽으로 넘어간다']::text[], array['그립 싸움 플로우 2분 — 패스는 하지 않고 그립만 다툰다','파트너 발 골반 가드에 좌우 스텝 패스 10회']::text[] from public.positions where slug = 'open-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['발 · 정강이 · 무릎으로 거리를 지킨다','그립을 잡고 상대 균형을 흔든다','스윕 · 일어서기 · 다른 가드로 전환한다']::text[], array['내 오른발 상대 왼쪽 골반, 내 오른손 상대 왼쪽 깃 · 소매','엉덩이를 계속 움직이고 등 전체를 바닥에 붙이지 않는다','상대가 내 오른쪽으로 돌면 오른쪽 어깨로 돌아누워 무릎을 다시 넣는다','발이 하나라도 상대 몸에 붙어 있게 한다']::text[], array['상대가 서서 거리를 벌리면 → 테크니컬 스탠드업 또는 신 투 신 가드','상대 왼발이 가까이 있으면 → 트라이포드 스윕 또는 시클 스윕','상대가 무릎을 넘기며 패스하려 하면 → 가드 리텐션 (다리 되돌리기) 또는 쉬림프 (힙 이스케이프)','상대가 숙이고 다가오면 → 칼라 드래그 (오픈 가드) 또는 트라이앵글 (오픈 가드)','상대 오른다리가 앞에 서 있으면 → 발 골반 → 데라히바']::text[], array['등을 대고 누워 있으면 상대가 다리를 쉽게 지나간다 → 앉거나 옆으로 돌아 무릎을 세운다','다리만 뻗고 그립이 없으면 상대가 발을 걷어낸다 → 손과 발을 같이 쓴다','스윕이 실패한 뒤 가만히 있으면 패스당한다 → 바로 다리를 되돌려 가드를 다시 만든다']::text[], array['쉬림프 · 다리 되돌리기 혼자 20회','파트너가 좌우로 걸으면 발을 계속 골반에 대며 따라가기 1분']::text[] from public.positions where slug = 'open-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['훅의 힘을 빼고 균형을 지킨다','상대 언더훅 · 그립을 끊는다','훅을 눌러 지나가거나 일어서서 패스한다']::text[], array['엉덩이를 낮추고 다리를 넓게 벌려 들리지 않는다','무게를 앞으로 싣지 않는다 — 앞으로 쏠리면 그대로 들려 넘어간다','상대 오른팔 언더훅을 막고 내 언더훅을 먼저 넣는다','무릎을 상대 몸 가운데로 모아 훅을 누른다']::text[], array['상대가 두 훅을 넣고 바로 앉아 있으면 → 버터플라이 훅 컨트롤 패스','상대가 뒤로 기대며 거리를 만들면 → 버터플라이 스매시 패스 또는 롱 스텝 패스','상대가 팔을 뻗어 거리를 두면 → 더블 언더 패스 (스택) 또는 오버 언더 패스','상대가 버터플라이 하프로 바꾸면 → 니슬라이스 패스']::text[], array['앞으로 기대며 누르면 훅에 그대로 들린다 → 엉덩이를 뒤로 두고 상체를 세운다','훅을 바깥으로 벌려 떼려 하면 더 단단히 걸린다 → 무릎을 가운데로 모아 누른다','언더훅을 내주면 엘리베이터 · 백 테이크가 온다 → 팔을 겨드랑이에 붙여 막는다']::text[], array['파트너가 훅으로 들어 올릴 때 넓은 베이스로 버티기 1분','훅 눌러 스매시 패스 10회']::text[] from public.positions where slug = 'butterfly-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['상체를 세우고 상대를 내 쪽으로 붙인다','언더훅 · 소매로 상대를 기울여 훅으로 들어 넘긴다','막히면 백 · X 가드로 이어 간다']::text[], array['내 오른팔 상대 왼팔 밑 언더훅, 내 왼손 상대 오른쪽 소매 · 손목','등은 세우고 머리는 상대 가슴 · 턱 밑에 붙인다','내 오른발 훅을 상대 왼쪽 허벅지 안에 걸어 둔다','눕는 것과 훅으로 드는 것을 한 번에 한다']::text[], array['상대가 무게를 앞으로 실으면 → 버터플라이 스윕 또는 엘리베이터 스윕','상대 오른팔이 뻗어 나오면 → 암 드래그 → 백 (버터플라이)','상대가 뒤로 버티며 서려 하면 → 버터플라이 → X 가드','상대 머리가 내 앞에 내려오면 → 길로틴 (버터플라이) 또는 길로틴 스윕 (버터플라이)','상대가 눌러 훅이 하나 빠지면 → 버터플라이 하프가드']::text[], array['등을 대고 누우면 훅이 힘을 못 쓴다 → 앉아서 상체를 세운다','언더훅 없이 훅만 쓰면 상대가 무겁게 누른다 → 언더훅 · 소매를 먼저 잡는다','발목을 상대 허벅지 밖에 두면 쉽게 패스당한다 → 훅을 허벅지 안쪽에 깊게 건다']::text[], array['앉은 자세에서 훅으로 파트너 다리 들기 · 내리기 20회','버터플라이 스윕 좌우 번갈아 10회']::text[] from public.positions where slug = 'butterfly-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['발목 그립을 먼저 떼고 훅을 무력화한다','상대 엉덩이 각도를 눕혀 정면으로 만든다','훅이 풀리면 바로 패스하고 누른다']::text[], array['상대 왼다리 훅이 내 오른다리에, 상대 왼손이 내 오른쪽 발목에 있다','상체는 세우고 엉덩이는 뒤로 — 앞으로 끌려가지 않는다','상대 오른발이 내 왼쪽 골반을 미는 걸 먼저 걷어낸다','중간 거리에 머물지 말고 붙거나 떨어진다']::text[], array['상대 발목 그립이 단단하면 → 토레안도 (데라히바 상대)','상대 훅이 얕거나 그립이 끊기면 → 니슬라이스 (데라히바 상대) 또는 레그 드래그 (데라히바 상대)','상대가 뒤집어 베림볼로를 노리면 → 백스텝 (데라히바 상대)','상대가 리버스 데라히바로 바꾸면 → 리버스 데라히바 패스 또는 백스텝 (RDLR 상대)']::text[], array['앞으로 기울면 훅과 발목 그립에 끌려 넘어간다 → 엉덩이를 빼고 머리는 엉덩이 위','발목 그립을 그대로 두면 균형을 계속 뺏긴다 → 내 왼손으로 바로 끊는다','상대 엉덩이가 비스듬히 선 걸 두면 베림볼로가 온다 → 상대 오른다리를 눌러 엉덩이를 눕힌다']::text[], array['발목 그립 끊기 → 토레안도 10회','파트너 데라히바에서 균형 지키며 좌우로 걷기 1분']::text[] from public.positions where slug = 'de-la-riva' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['훅과 발목 그립으로 상대 오른다리를 붙잡는다','상대를 앞뒤로 흔들어 스윕하거나 등으로 돈다','패스가 오면 리버스 · X 가드로 바꿔 다리를 지킨다']::text[], array['내 왼다리 상대 오른다리 바깥 훅, 내 왼손 상대 오른쪽 발목','내 오른발 상대 왼쪽 골반, 내 오른손 상대 왼쪽 소매 · 깃','엉덩이는 상대 오른다리 쪽으로 비스듬히 두고 바닥에 붙이지 않는다','훅은 걸어만 두지 말고 당기고 밀며 계속 흔든다']::text[], array['상대가 앞으로 무게를 실으면 → 데라히바 스윕','상대가 뒤로 버티며 서 있으면 → 베림볼로 또는 데라히바 백 테이크 (앉혀서 돌기)','상대가 다리 쪽으로 넘어오려 하면 → 데라히바 → X 가드','상대가 무릎을 안으로 넣어 훅을 풀면 → 리버스 데라히바 가드','상대가 상체를 숙이면 → 트라이앵글 (데라히바) 또는 오모플라타 (데라히바)']::text[], array['발목 그립 없이 훅만 걸면 상대가 다리를 빼 패스한다 → 발목을 먼저 잡는다','등을 대고 정면으로 누우면 흔들 힘이 없다 → 엉덩이를 비스듬히 세운다','오른발을 골반에서 떼면 상대가 붙어 눌러 온다 → 오른발로 거리를 지킨다']::text[], array['데라히바 잡고 파트너를 앞뒤로 흔들기 1분','데라히바 → 리버스 데라히바 → 데라히바 전환 10회']::text[] from public.positions where slug = 'de-la-riva' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['소매 그립과 발 프레임으로 상대를 내 거리 밖에 묶어 둔다','밀고 당기기를 반대로 써 상대 균형을 무너뜨려 스윕한다','상대가 버티며 팔을 당기면 트라이앵글·오모플라타로 상대 오른팔을 공격한다']::text[], array['소매는 손목 끝 천을 깊게 쥐고 손목을 말아 놓치지 않는다','내 왼발은 상대 오른쪽 이두를 계속 밀고, 발이 눌리면 바로 다른 자리로 옮긴다','엉덩이를 바닥에 붙이지 말고 살짝 들어 각도를 계속 바꾼다','라쏘는 내 왼다리를 상대 오른팔에 깊게 감아 팔을 빼지 못하게 한다']::text[], array['상대가 무릎 꿇고 버티며 체중을 앞에 두면 → 스파이더 스윕','상대가 내 왼발을 이두에서 걷어 내려 하면 → 스파이더 → 라쏘','상대가 라쏘 쪽 팔을 당기며 일어서면 → 라쏘 스윕 또는 오모플라타 (라쏘)','상대가 상체를 숙여 앞으로 들어오면 → 트라이앵글 (스파이더)','상대가 다리 쪽으로 돌아 패스를 시작하면 → 칼라 슬리브 → 데라히바']::text[], array['발로 밀지 않고 손으로만 당기면 상대가 쉽게 다가와 눌러 버린다 → 손으로 당길 때 발은 반드시 민다','엉덩이를 바닥에 붙인 채 버티면 각도가 안 나와 스윕이 막힌다 → 한쪽 엉덩이를 들어 비스듬히 눕는다','그립이 끊긴 뒤에도 같은 그립만 다시 찾으면 상대가 다리를 잡고 패스한다 → 먼저 발로 골반을 막고 그 다음 그립을 다시 잡는다']::text[], array['파트너가 무릎 꿇고 소매를 빼려 할 때 스파이더 → 라쏘 → 스파이더로 발 위치만 바꾸며 3분 유지하기','혼자 누워 양발을 번갈아 뻗고 당기는 자전거 동작으로 발 프레임 감각 익히기']::text[] from public.positions where slug = 'spider-lasso' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['패스보다 먼저 소매 그립과 발 프레임을 하나씩 끊는다','끊은 순간 다리를 잡고 눌러 다시 가드를 못 만들게 한다','상대 오른쪽 사이드까지 가서 자리를 굳힌다']::text[], array['허리를 세우고 발을 넓게 벌려, 당겨도 앞으로 쏠리지 않게 선다','이두를 미는 발과 팔 힘으로 싸우지 말고, 거리와 자세로 힘을 뺀다','그립은 두 손으로 한 소매를 잡아 떼거나 손목을 돌려 끊는다','라쏘가 들어오기 시작하면 내 오른팔 팔꿈치를 바로 몸 쪽으로 붙인다']::text[], array['상대가 양 소매·양발 스파이더를 꽉 잡고 있으면 → 스파이더 가드 패스','상대가 트라이앵글·오모플라타로 발을 떼며 들어오면 → 스택 패스 (스파이더 상대)','상대가 왼다리로 내 오른팔에 라쏘를 걸면 → 라쏘 가드 패스 또는 백스텝 패스 (라쏘 상대)','상대가 칼라 슬리브로 깃과 소매를 잡고 버티면 → 불 패스 (칼라 슬리브 상대)','그립을 끊었는데 상대 다리가 아직 느슨하면 → 토레안도 패스']::text[], array['그립이 붙은 채 앞으로 들어가면 상대 발 위에 체중이 실려 스윕당한다 → 그립을 끊은 다음 들어간다','발을 좁게 모으고 서면 작은 당김에도 넘어간다 → 발을 상대 골반 바깥 넓이로 벌린다','라쏘가 깊어질 때까지 두면 빼기 어렵고 오모플라타가 열린다 → 걸리는 순간 팔꿈치를 붙이고 풀기 시작한다']::text[], array['파트너가 스파이더를 잡고 버틸 때 소매 끊기만 1분씩 반복하고, 끊으면 바로 바지를 잡고 멈추기','스파이더에서 시작해 위는 패스, 아래는 스윕만 하는 3분 부분 스파링']::text[] from public.positions where slug = 'spider-lasso' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['상대가 그립을 잡기 전에 라펠을 꺼내 상대 오른다리에 감아 둔다','묶인 오른다리 쪽(내 왼쪽)으로 스윕하거나 백을 노린다','패스 시도가 오면 데라히바·라쏘·스파이더로 갈아 끼워 가드를 유지한다']::text[], array['라펠은 상대 오른다리 오금 뒤로 깊게 돌려야 다리가 묶인다','내 왼손이 라펠 끝을 놓치지 않게 손목을 말아 짧게 잡는다','웜 가드에서는 내 왼발을 상대 오른쪽 골반에 대 거리를 지킨다','한쪽으로 비스듬히 누워 엉덩이를 계속 움직여 상대 체중이 실리지 않게 한다']::text[], array['상대가 서서 오른다리에 체중을 실으면 → 라펠 엘리베이터 스윕','상대가 라펠을 떼려고 몸을 돌리면 → 라펠 스윕 → 백','상대가 무릎을 꿇어 자세를 낮추면 → 웜 가드 진입 후 웜 가드 스윕','상대가 다리를 빼며 패스를 시작하면 → 라펠 → 데라히바 또는 라펠 → 라쏘','상대가 상체를 숙여 들어오면 → 트라이앵글 (라펠) 또는 오모플라타 (라펠)']::text[], array['라펠을 얕게 돌리면 상대가 다리만 빼도 풀린다 → 오금 뒤까지 깊게 돌린다','라펠을 감는 데만 집중하면 상대가 그 사이 무릎을 넘어온다 → 감는 동안 내 오른발로 상대 왼쪽 골반을 막는다','평평하게 누운 채 라펠만 당기면 힘만 들고 스윕이 안 된다 → 비스듬히 누워 각도를 만든 뒤 당긴다']::text[], array['파트너가 서 있을 때 라펠을 꺼내 오른다리 뒤로 돌려 잡는 동작만 10번 반복','라펠 가드에서 시작해 아래는 스윕, 위는 라펠 풀기만 하는 2분 부분 스파링']::text[] from public.positions where slug = 'lapel-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['라펠이 다리에 감기기 전에 막고, 감겼으면 패스보다 먼저 푼다','푼 순간 바로 눌러서 다시 감지 못하게 한다','상대 왼쪽으로 돌아 패스를 끝낸다']::text[], array['내 왼손으로 상대 오른쪽 손목을 눌러 라펠을 당기지 못하게 한다','라펠은 힘으로 뜯지 말고 다리를 빼거나 감긴 방향 반대로 풀어 낸다','거리를 만들 땐 한 발 물러서 상대 다리 힘이 닿지 않게 한다','한 자리에 오래 서 있지 말고 계속 각도를 바꿔 라펠을 다시 감지 못하게 한다']::text[], array['상대가 라펠을 오른다리에 감기 시작하면 → 라펠 풀고 토레안도','상대가 웜 가드를 완성하면 → 거리 만들어 리셋 (라펠 상대) 또는 웜 가드 상대 자세 지키기','상대 라펠 그립이 잡혀 있어도 무릎이 바닥에 닿아 있으면 → 니슬라이스 (라펠 잡힌 채)','상대가 라펠을 쥔 채 다리가 바닥으로 내려오면 → 레그 드래그 (라펠 풀며)','상대가 라펠로 당기며 엉덩이를 들면 → 스택 패스 (라펠 상대)']::text[], array['라펠을 감긴 채로 압박 패스를 하면 천이 막아서 붙지 못하고 스윕당한다 → 먼저 라펠을 풀고 들어간다','감긴 라펠을 손힘으로 뜯으면 손만 지친다 → 다리를 빼거나 감긴 방향 반대로 푼다','뒤로만 물러서면 위치가 다시 처음으로 돌아간다 → 푸는 동작과 패스 각도를 같이 만든다']::text[], array['파트너가 라펠을 꺼내려 할 때 손목을 눌러 막는 그립 싸움 30초 반복','웜 가드를 걸어 둔 채 시작해 라펠을 풀고 사이드까지 가는 동작 5번']::text[] from public.positions where slug = 'lapel-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['상대 한 다리를 묶어 무게를 받칠 다리를 없앤다','다리를 펴고 당겨 상대를 띄워 스윕하고 일어선다','상대가 다리를 빼면 싱글 레그 X로 바꿔 스윕이나 앵클락을 노린다']::text[], array['상대 왼다리를 내 오른팔로 꽉 안고 머리를 그 다리 가까이 둔다','내 왼발은 상대 오른쪽 오금 깊이 걸고, 내 오른발로 상대 허벅지를 밀어 X 모양을 유지한다','엉덩이를 상대 다리 밑으로 붙여 넣어 상대가 내 위로 무게를 싣게 한다','스윕 뒤에는 상대 다리를 안은 채 바로 일어서 위를 차지한다']::text[], array['상대가 앞으로 몸을 숙여 무게를 실으면 → X 가드 스윕','상대가 뒤로 버티며 다리를 빼려 하면 → 토마호크 스윕 또는 X 가드 → 일어나기','상대가 묶인 다리를 뒤로 빼면 → X 가드 → 싱글 레그 X','상대 왼발이 내 오른쪽 겨드랑이에 안긴 채 서 있으면 → 싱글 레그 X 스윕 또는 스트레이트 앵클락','상대가 등을 돌리며 빠지려 하면 → X 가드 → 백 테이크']::text[], array['상대 다리를 느슨하게 안으면 상대가 다리를 빼고 눌러 버린다 → 머리와 팔을 다리에 붙여 꽉 안는다','오금 훅이 얕으면 다리를 펴도 상대가 뜨지 않는다 → 내 왼발을 오금 깊이 건다','스윕하고 누운 채 있으면 상대가 다시 가드를 만든다 → 넘어가는 순간 일어서서 위로 올라간다']::text[], array['파트너가 서 있을 때 앉은 자세에서 다리 밑으로 들어가 X 가드를 만드는 진입 10번','X 가드에서 파트너가 무게를 앞·뒤로 옮길 때마다 맞는 스윕 방향으로 다리를 펴는 반응 연습']::text[] from public.positions where slug = 'x-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['묶인 다리를 지키며 넘어가지 않을 만큼 자세를 낮춘다','상대 훅 두 개 중 하나를 먼저 떼어 X 모양을 무너뜨린다','훅이 풀리면 다리를 누르고 패스해 사이드로 간다']::text[], array['똑바로 서지 말고 무릎을 굽혀 엉덩이를 낮추고 몸을 살짝 앞으로 둔다','풀린 오른발은 넓게 짚어 넘어지지 않을 바닥을 만든다','상대 소매·깃 그립을 떼서 내 상체를 끌고 다니지 못하게 한다','오금에 걸린 훅이 가장 위험하니 그 훅부터 떼어 낸다']::text[], array['상대 훅이 깊고 나를 띄우기 시작하면 → 스매시 패스 (X 가드 상대)','상대 훅이 얕거나 지쳐 느슨하면 → 무릎 눌러 X 가드 패스 또는 스텝 오버 (X 가드 상대)','아직 서 있을 수 있고 거리가 있으면 → X 가드 빠져나오기 (서서)','상대가 싱글 레그 X로 바꾸면 → 싱글 레그 X 빠져나오기 (서서) 또는 백스텝 (싱글 레그 X 상대)','상대가 내 왼발에 앵클락을 걸면 → 앵클락 빠져나오기']::text[], array['다리를 좁게 붙이고 똑바로 서면 조금만 띄워도 넘어간다 → 무릎을 굽히고 자유로운 발을 넓게 짚는다','훅을 그대로 둔 채 넘어가려 하면 그 순간 스윕당한다 → 훅을 먼저 떼고 넘어간다','앵클락에 걸렸는데 다리를 당기기만 하면 발목이 더 잠긴다 → 발끝을 세우고 상대 다리를 막으며 무릎을 빼낸다']::text[], array['X 가드에 걸린 채 시작해 위는 훅 떼기, 아래는 스윕만 하는 3분 부분 스파링','앵클락이 걸린 자세에서 천천히 발끝 세우고 무릎 빼기 동작만 5번 반복']::text[] from public.positions where slug = 'x-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['평평하게 눌리지 않게 옆으로 누워 프레임을 세운다','내 왼팔 언더훅을 먼저 차지해 옆으로 올라온다','스윕하거나 백을 잡고, 안 되면 니 쉴드로 거리를 다시 만든다']::text[], array['내 오른쪽 어깨와 엉덩이를 바닥에 대고 몸을 상대 쪽(내 왼쪽)으로 세운다','내 왼팔은 상대 오른쪽 겨드랑이 밑으로 깊게 언더훅, 머리는 상대 가슴 밑에 붙인다','프레임은 내 오른쪽 팔뚝 상대 목, 왼쪽 팔뚝 상대 오른쪽 골반','엉덩이를 내 오른쪽으로 빼 공간을 만들고 내 왼쪽 무릎을 니 쉴드로 넣는다']::text[], array['상대가 언더훅을 내주고 상체가 떠 있으면 → 하프가드 언더훅 잡기 후 올드 스쿨 스윕','상대가 언더훅에 위저로 막으며 버티면 → 도그파이트 스윕 또는 하프가드 백 테이크','상대가 앞으로 눌러 들어오면 → 니 쉴드 하프가드 후 니 쉴드 스윕','상대 오른팔이 바닥을 짚고 팔꿈치가 벌어지면 → 기무라 (하프가드)','상대 크로스페이스에 등이 눌리면 → 눌린 하프가드에서 회복 또는 눌린 하프 → 딥 하프']::text[], array['등을 바닥에 대고 평평하게 누우면 크로스페이스에 눌려 패스당한다 → 바로 오른쪽 어깨로 돌아누워 옆으로 선다','언더훅을 상대에게 주면 내 위로 눌려 움직일 수 없다 → 내 왼팔을 먼저 넣어 겨드랑이를 차지한다','다리만 꽉 조이고 상체를 비우면 다리가 풀릴 때 바로 사이드가 된다 → 프레임과 언더훅을 다리보다 먼저 챙긴다']::text[], array['파트너가 크로스페이스를 시도할 때 오른쪽 어깨로 돌아누워 왼팔 언더훅을 넣는 동작 10번','하프가드에서 시작해 아래는 언더훅 차지, 위는 크로스페이스 차지만 하는 1분 싸움']::text[] from public.positions where slug = 'half-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['상체를 먼저 눌러 상대를 평평하게 만든다','감긴 내 오른다리를 천천히 빼 하프를 풀어 낸다','사이드나 마운트로 가서 자리를 굳힌다']::text[], array['내 오른팔 크로스페이스로 상대 얼굴을 상대 오른쪽으로 돌린다','상대 왼팔 언더훅을 막고 내 왼팔로 상대 오른팔 밑 언더훅을 차지한다','엉덩이를 낮추고 가슴으로 눌러 상대가 옆으로 돌아누울 공간을 없앤다','니 쉴드(상대 왼쪽 무릎)는 내 왼손으로 눌러 바닥으로 내린다']::text[], array['상대가 평평하게 누워 있고 니 쉴드가 없으면 → 하프가드 패스 (크로스페이스 · 언더훅)','상대가 니 쉴드로 막고 있으면 → 스매시 패스 또는 니슬라이스 패스','상대가 언더훅을 넣고 올라오면 → 하프 탑 위저 카운터 또는 바디락 패스','상대 다리가 내 오른쪽 발목까지 밀려 내려가면 → 하프가드 → 쿼터 가드 (탑) 후 쿼터 가드 패스','상대가 프레임 없이 목이 비면 → 암 트라이앵글 (하프 탑) 또는 루프 초크 (하프 탑)']::text[], array['크로스페이스 없이 다리부터 빼면 상대가 옆으로 올라와 스윕한다 → 상체를 먼저 누르고 다리를 뺀다','상대에게 언더훅을 내주면 도그파이트로 밀려 백까지 위험하다 → 겨드랑이를 붙이고 위저로 막는다','한 번에 다리를 확 빼려 하면 균형이 무너진다 → 조금씩 빼며 체중은 계속 상대 위에 둔다']::text[], array['하프 탑에서 크로스페이스와 언더훅을 잡고 30초 동안 상대가 옆으로 못 돌게 누르기','하프 탑에서 다리 빼기 → 사이드 안착까지 천천히 5번 반복']::text[] from public.positions where slug = 'half-guard' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['상대 오른다리 밑 깊이 들어가 상대 무게를 내 쪽으로 싣게 한다','상대 무게가 앞뒤로 쏠리는 쪽에 맞춰 스윕한다','스윕이 막히면 백이나 X 가드로 옮겨 간다']::text[], array['내 오른팔로 상대 오른쪽 허벅지를 깊게 안고 놓치지 않는다','머리는 상대 다리 사이 밑에 숨겨 크로스페이스가 닿지 않게 한다','내 왼손은 상대 왼쪽 발목이나 허리띠를 잡아 상대 균형을 조종한다','양다리로 상대 오른다리를 감아 다리를 빼지 못하게 한다']::text[], array['상대가 앞으로 무게를 실으면 → 웨이터 스윕','상대가 뒤로 무게를 빼며 버티면 → 딥 하프 스윕 또는 호머 심슨 스윕','상대가 다리를 빼려 일어서면 → 딥 하프 → X 가드','상대가 옆으로 돌아 등을 보이면 → 딥 하프 → 백 테이크']::text[], array['머리를 상대 다리 밖에 두면 크로스페이스에 눌려 다시 평평해진다 → 머리를 다리 사이 밑으로 숨긴다','허벅지를 얕게 안으면 상대가 다리를 빼고 패스한다 → 오른팔을 허벅지 위쪽까지 깊게 감는다','힘으로 한 번에 들어 넘기려 하면 상대가 무게를 바꿔 막는다 → 상대가 쏠리는 방향을 따라 넘긴다']::text[], array['눌린 하프에서 딥 하프로 미끄러져 들어가는 진입만 10번','딥 하프에서 파트너가 무게를 앞·뒤로 바꿀 때마다 웨이터와 호머 심슨을 번갈아 쓰는 반응 연습']::text[] from public.positions where slug = 'deep-half' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['넘어가지 않게 넓게 서서 무게를 가운데 둔다','상대 머리를 눌러 깊이 들어온 자세를 무너뜨린다','안긴 오른다리를 빼고 패스한다']::text[], array['내 왼다리를 멀리 넓게 짚어 세 점(양발·손)으로 버틴다','무게를 너무 앞이나 뒤로 두지 말고 가운데에 둔다','내 왼손으로 상대 상체·머리를 눌러 바닥에 붙이고 오른팔은 위저로 막는다','상대가 허리띠·발목을 잡으면 그 손부터 뗀다']::text[], array['상대가 상체를 비워 두고 깊이 들어와 있으면 → 위저 (딥 하프 상대)','상대가 스윕하려 다리를 밀며 엉덩이를 띄우면 → 백스텝 (딥 하프 상대)','상대가 딥 하프를 놓쳐 평평해지면 → 니슬라이스 (딥 하프 상대)','상대 머리가 밖으로 나와 있으면 → 하프가드 패스 (크로스페이스 · 언더훅)']::text[], array['다리를 빼려고 세게 비틀면 그 힘으로 스윕당한다 → 머리를 먼저 누르고 천천히 뺀다','무게를 너무 앞에 두면 웨이터, 너무 뒤에 두면 다른 스윕에 넘어간다 → 가운데에 두고 왼다리를 넓게 짚는다','오래 버티기만 하면 상대가 그립을 완성한다 → 위저·머리 누르기·다리 빼기를 순서대로 바로 시작한다']::text[], array['파트너가 딥 하프에서 어떤 스윕을 할지 다리를 툭 쳐서 알려 주면 그 반대로 무게를 옮기는 반응 연습','딥 하프 탑에서 머리 누르기 → 위저 → 다리 빼기 → 사이드까지 천천히 5번']::text[] from public.positions where slug = 'deep-half' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['상대 다리(발 · 정강이 · 무릎)를 치우고 그 옆을 지나간다','지나간 뒤 상대 오른쪽 사이드에 가슴을 붙여 자리를 굳힌다','패스 중에 스윕 · 서브미션을 당하지 않는다']::text[], array['허리는 세우고 엉덩이는 뒤로, 머리는 엉덩이보다 앞으로 숙이지 않는다','먼저 그립 싸움에서 이긴다 — 상대 손을 떼고 내 손은 바지 · 무릎 · 발목에','상대 다리는 상대 왼쪽(내 오른쪽)으로 몰고 내 발은 내 왼쪽으로 옮겨 상대 오른쪽 사이드로 끝낸다','지나가는 순간 내 왼팔로 크로스페이스를 해 상대 얼굴을 상대 왼쪽으로 돌린다']::text[], array['상대가 발로 내 골반을 밀며 거리를 두면 → 토레안도 패스 또는 롱 스텝 패스','상대가 앉아서 무릎을 세우고 버티면 → 니슬라이스 패스 또는 바디락 패스 (시팅 가드 상대)','상대 다리가 길게 펴지고 엉덩이가 바닥에 붙으면 → 레그 드래그','상대가 누워서 다리를 높이 들고 버티면 → 더블 언더 패스 (스택)','패스는 했는데 아직 상대가 움직이면 → 패스 마무리 (사이드 안착)']::text[], array['상체를 숙이고 엉덩이를 상대에게 붙이면 앞으로 끌려가 스윕된다 → 허리를 세우고 엉덩이를 뒤로 뺀다','그립 없이 바로 돌아가려 하면 상대가 따라와 가드를 다시 만든다 → 바지나 무릎을 먼저 잡고 움직인다','다리를 지나자마자 손을 놓으면 상대가 무릎을 다시 넣는다 → 크로스페이스와 골반 차단까지 하고 멈춘다']::text[], array['파트너가 누워 다리만 움직이고, 나는 토레안도 → 레그 드래그 → 니슬라이스를 번갈아 30초씩 사이드까지 간다','그립 싸움만 하기 — 서로 패스 · 스윕 없이 3분 동안 상대 손을 떼고 내 그립을 잡는다']::text[] from public.positions where slug = 'passing' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['상대가 내 다리 옆을 지나가지 못하게 다리를 상대와 나 사이에 둔다','상대 오른쪽(내 오른쪽)으로 넘어오면 무릎을 다시 넣어 가드를 되찾는다','상대가 균형을 잃으면 스윕으로 바꾼다']::text[], array['엉덩이와 얼굴은 늘 상대를 본다 — 등이 바닥에 납작하게 붙지 않게 옆으로 누운다','내 오른 팔꿈치와 오른 무릎을 붙여 오른쪽 옆구리 틈을 닫는다','발 · 정강이 · 무릎으로 상대 골반과 어깨에 프레임을 만들어 거리를 지킨다','상대가 내 깃이나 바지를 잡으면 바로 그립부터 뗀다']::text[], array['상대가 컴뱃 베이스로 무릎을 세우고 누르면 → 컴뱃 베이스 상대 가드 회복','상대가 헤드쿼터로 무릎을 내 다리 사이에 넣으면 → 헤드쿼터 상대 신 투 신 또는 헤드쿼터 상대 인버트 → 데라히바','상대가 레그 드래그로 다리를 끌어가면 → 레그 드래그 상대 하프 회복 또는 레그 드래그 상대 데라히바 회복','상대가 양팔로 내 다리를 감아 스택하면 → 더블 언더 상대 가드 회복','상대가 패스하려고 한쪽으로 크게 기울면 → 카운터 스윕 (패스 중)']::text[], array['등을 바닥에 대고 누워 있으면 상대가 쉽게 옆으로 돈다 → 옆으로 누워 엉덩이를 계속 움직인다','다리를 다 놓친 뒤에야 막으려 하면 이미 늦다 → 상대 무릎이 지나오기 전에 팔꿈치 · 무릎을 붙인다','팔을 쭉 펴서 밀기만 하면 힘이 빠지고 팔을 잡힌다 → 팔뚝 · 정강이로 프레임을 세우고 엉덩이를 뺀다']::text[], array['가드 리텐션 라운드 — 상대는 패스만, 나는 스윕 없이 다리만 다시 넣기를 1분씩','혼자 새우빼기 · 엉덩이 들어 돌기를 좌우 10번씩']::text[] from public.positions where slug = 'passing' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['상대가 무릎을 넣거나 몸을 돌리지 못하게 자리를 지킨다','마운트나 니 온 밸리로 더 좋은 자리를 간다','상대가 팔을 내놓으면 서브미션을 건다']::text[], array['양 무릎을 상대 오른쪽 옆구리에 붙이고 엉덩이는 낮게 둔다','내 왼팔로 크로스페이스 — 상대 얼굴을 상대 왼쪽으로 돌려 놓는다','내 오른팔로 상대 오른팔(가까운 팔)을 막고 상대 골반에 붙여 무릎이 못 들어오게 한다','무게는 손이 아니라 가슴과 엉덩이로 싣는다']::text[], array['상대가 왼팔을 펴서 내 목이나 얼굴을 밀면 → 아메리카나 (사이드) 또는 기무라 (사이드)','상대가 무릎을 넣으려 하면 → 사이드 → 니 온 밸리 또는 사이드에서 마운트 가기','상대가 나를 향해 돌아 들어오면 → 남북 또는 다스 초크','상대 왼팔이 상대 목 앞을 지나가면 → 암 트라이앵글 (헤드 앤 암)','상대가 계속 버티기만 하면 → 사이드 컨트롤 유지']::text[], array['엉덩이를 높이 들면 상대 무릎이 들어와 하프가드가 된다 → 엉덩이를 내리고 무릎을 옆구리에 붙인다','크로스페이스가 느슨하면 상대가 나를 향해 돌아 빠진다 → 왼팔로 얼굴을 계속 상대 왼쪽으로 밀어 둔다','서브미션만 쫓다 무게를 빼면 자리를 잃는다 → 자리를 먼저 지키고 팔이 나올 때만 건다']::text[], array['파트너가 절반 힘으로 빠져나오고 나는 1분 동안 사이드 컨트롤 유지만, 5라운드','사이드 → 니 온 밸리 → 마운트 → 사이드를 쉬지 않고 10바퀴']::text[] from public.positions where slug = 'side-control' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['목과 팔을 지키며 숨 쉴 공간을 만든다','엉덩이를 빼서 무릎을 넣고 가드나 하프가드를 되찾는다','안 되면 터틀이나 무릎으로 일어나 다시 시작한다']::text[], array['내 오른 팔꿈치 · 팔뚝은 상대 골반에, 왼 팔뚝은 상대 목에 프레임','팔은 몸에 붙인다 — 팔을 펴서 밀면 아메리카나 · 기무라를 당한다','엉덩이는 내 왼쪽으로 빼고 생긴 틈에 내 오른 무릎을 넣는다','옆으로 누워 상대를 본다 — 등이 바닥에 붙으면 아무것도 못 한다']::text[], array['상대 무게가 가슴에 실려 있으면 → 사이드 이스케이프 (프레임 · 쉬림프)','상대가 내 머리 쪽으로 무게를 옮기면 → 터틀로 돌기 (사이드) 또는 싯아웃 (사이드)','상대가 마운트로 다리를 넘기려 하면 → 브릿지 앤 롤 (사이드) 또는 고스트 이스케이프','상대가 팔을 잡아 고정하려 하면 → 팔 빼내기 (사이드 아래)']::text[], array['팔을 쭉 펴서 상대를 밀면 팔을 잡힌다 → 팔꿈치를 굽혀 팔뚝으로 프레임한다','브릿지만 하고 엉덩이를 안 빼면 제자리로 돌아온다 → 브릿지로 띄운 순간 엉덩이를 내 왼쪽으로 뺀다','상대에게 등을 보이며 돌면 백을 준다 → 무릎을 넣거나 터틀에서 바로 무릎 · 손으로 버틴다']::text[], array['프레임 → 브릿지 → 새우빼기 → 무릎 넣기를 파트너가 가볍게 누른 상태로 좌우 10번','혼자 새우빼기로 매트 끝까지 왕복']::text[] from public.positions where slug = 'side-control' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['가슴으로 상대 가슴을 눌러 움직이지 못하게 한다','상대 팔 하나를 묶어 서브미션(초크 · 기무라)으로 간다','상대가 빠져나오려 하면 사이드나 백으로 옮긴다']::text[], array['가슴은 상대 가슴 · 어깨 위에 — 배나 엉덩이 쪽으로 물러나지 않는다','엉덩이는 낮게, 무릎은 넓게 벌려 굴러가지 않게 받친다','상대 오른팔부터 묶는다 — 팔이 자유로우면 프레임을 만든다','서브미션을 노릴 때도 가슴 압박을 풀지 않는다']::text[], array['상대가 납작하게 누워 팔을 몸에 붙이고 있으면 → 남북 초크','상대 오른팔이 바닥에서 들리면 → 남북 기무라 또는 아메리카나 (남북)','상대가 양손으로 내 골반을 밀며 빠지려 하면 → 남북 → 사이드','상대가 엎드려 터틀이 되면 → 백 테이크 (남북, 상대가 엎드릴 때)']::text[], array['무게를 상대 다리 쪽으로 빼면 상대가 브릿지로 돌린다 → 가슴을 상대 머리 쪽으로 싣는다','무릎을 좁게 모으면 상대가 옆으로 굴린다 → 무릎을 넓히고 엉덩이를 낮춘다','상대가 프레임을 다 만든 뒤에도 남북에 버티면 힘만 쓴다 → 사이드로 돌아간다']::text[], array['사이드 → 남북 → 상대 왼쪽 사이드로 돌기를 가슴을 떼지 않고 10바퀴','파트너가 빠져나오고 나는 남북만 1분 유지, 5라운드']::text[] from public.positions where slug = 'north-south' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['목과 팔을 먼저 지킨다','상대 골반에 프레임을 만들어 공간을 낸다','몸을 돌려 무릎을 넣거나 터틀로 간다']::text[], array['양손으로 상대 골반에 프레임 — 상대 엉덩이가 내 머리 쪽으로 오지 못하게','턱을 당기고 팔꿈치를 몸에 붙인다 — 목과 팔 사이 틈을 주지 않는다','내 오른쪽으로 돌아 나온다','엉덩이를 들썩이며 상대 무게를 흔든다']::text[], array['상대 골반에 프레임이 들어가면 → 남북 이스케이프','상대 무게가 가슴 위로 높게 올라오면 → 남북 → 터틀','상대가 다시 옆으로 돌아 사이드로 누르면 → 사이드 이스케이프 (프레임 · 쉬림프)']::text[], array['팔을 상대 등 위로 감으면 기무라 · 초크를 당한다 → 팔은 상대 골반 쪽 프레임에 둔다','턱을 들고 있으면 남북 초크가 들어온다 → 턱을 당기고 고개를 돌려 목을 지킨다','엎드리면서 무릎 · 팔꿈치를 안 모으면 백을 준다 → 팔꿈치와 무릎을 붙여 터틀을 단단히 만든다']::text[], array['파트너가 남북으로 누르고 나는 골반 프레임 → 오른쪽으로 돌아 무릎 넣기를 10번']::text[] from public.positions where slug = 'north-south' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['무릎 압박으로 상대가 반응하게 만든다','상대가 밀면 서브미션, 돌면 마운트나 백으로 간다','상대가 빠지면 바로 사이드로 내려가 자리를 지킨다']::text[], array['내 오른쪽 무릎은 상대 명치 · 아랫갈비에 — 가슴 위로 너무 올리지 않는다','내 왼손 상대 오른쪽 깃, 내 오른손 허리띠나 바지','내 왼다리는 넓게 펴서 버티고 발로 가볍게 움직일 준비','엉덩이는 들고 몸은 앞으로 — 뒤로 앉지 않는다']::text[], array['상대가 왼팔로 내 무릎이나 다리를 밀면 → 파 사이드 암바 (니 온 밸리)','상대가 가만히 버티면 → 베이스볼 배트 초크 또는 크로스 칼라 초크 (니 온 밸리)','상대가 내 무릎을 피해 엉덩이를 빼면 → 니 온 밸리 → 마운트 또는 니 온 밸리 → 사이드','상대가 등을 돌려 엎드리려 하면 → 백 테이크 (니 온 밸리, 상대가 돌아설 때)','상대가 내 쪽으로 돌아 들어오면 → 니 온 밸리 스위치 (반대쪽으로 옮기기)']::text[], array['무릎에 무게를 다 싣고 멈추면 균형을 잃고 스윕된다 → 발은 가볍게, 계속 조정한다','버티는 다리를 상대 몸에 붙이면 상대가 다리를 잡고 넘긴다 → 왼다리를 넓게 편다','그립 없이 무릎만 올리면 상대가 쉽게 돈다 → 깃과 허리띠를 잡고 올린다']::text[], array['사이드 → 니 온 밸리 → 상대 왼쪽 니 온 밸리 → 사이드를 쉬지 않고 10바퀴','파트너가 절반 힘으로 빠지고 나는 니 온 밸리 유지만 1분, 5라운드']::text[] from public.positions where slug = 'knee-on-belly' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['배 위 무릎을 밀어 숨을 쉬고 무게를 뺀다','엉덩이를 빼서 무릎을 넣고 가드를 되찾는다','팔을 내주지 않는다']::text[], array['양 팔뚝으로 상대 오른 무릎 · 골반에 프레임','엉덩이를 내 왼쪽으로 빼고 생긴 틈에 내 오른 무릎을 넣는다','팔을 쭉 펴서 상대 몸을 밀지 않는다 — 팔꿈치는 굽혀 붙인다','상대에게 등을 돌리지 않는다']::text[], array['상대 무릎에 프레임이 들어가면 → 니 온 밸리 이스케이프','상대 무게가 앞으로 쏠려 무릎이 무거우면 → 터틀로 돌기 (니 온 밸리 아래)','상대가 무릎을 내리고 사이드로 누르면 → 사이드 이스케이프 (프레임 · 쉬림프)']::text[], array['팔을 펴서 상대 가슴을 밀면 파 사이드 암바를 당한다 → 팔꿈치를 굽혀 무릎 쪽만 민다','상대에게 등을 보이며 내 왼쪽으로 엎드리면 백을 준다 → 상대 쪽을 보며 엉덩이를 뺀다','누운 채 버티기만 하면 계속 눌린다 → 바로 프레임과 엉덩이 빼기를 시작한다']::text[], array['파트너가 니 온 밸리로 가볍게 누르고 나는 프레임 → 새우빼기 → 무릎 넣기를 10번']::text[] from public.positions where slug = 'knee-on-belly' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['상대 머리와 오른팔을 묶어 몸을 못 돌리게 누른다','상대가 빼려는 팔을 서브미션으로 바꾼다','버티기 힘들면 사이드나 마운트로 옮긴다']::text[], array['상대 오른팔을 내 왼 겨드랑이에 꽉 끼우고, 내 오른팔로 목 뒤를 감는다','내 오른다리는 앞, 왼다리는 뒤로 넓게 벌려 굴러가지 않게 받친다','엉덩이는 바닥에 낮게, 무게는 가슴 옆구리로 상대 가슴에','내 등이 상대 쪽으로 드러나니 상대 왼손이 등 뒤로 오는지 본다']::text[], array['상대가 왼팔로 내 얼굴을 밀면 → 아메리카나 (곁누르기) 또는 기무라 (곁누르기)','상대가 끼인 오른팔을 펴서 빼려 하면 → 스트레이트 암락 (곁누르기)','상대가 브릿지로 나를 넘기려 하면 → 곁누르기 → 사이드','상대가 목을 빼려 하면 → 변형 곁누르기','상대 다리가 멀리 있고 엉덩이가 납작하면 → 곁누르기 → 마운트']::text[], array['상대 가슴 위에 높이 앉으면 브릿지에 넘어간다 → 엉덩이를 바닥으로 내린다','다리를 모으면 굴러간다 → 오른다리는 앞, 왼다리는 뒤로 넓게','서브미션 하려고 목을 놓으면 상대가 바로 돌아 들어온다 → 목 · 팔을 잡은 채로 건다']::text[], array['파트너가 브릿지 · 새우빼기로 빠지고 나는 곁누르기 유지만 1분, 5라운드','곁누르기 → 변형 곁누르기 → 리버스 곁누르기 → 사이드 흐르기 10바퀴']::text[] from public.positions where slug = 'kesa-gatame' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['끼인 오른팔과 목을 지킨다','상대를 브릿지로 흔들어 등이나 가드를 찾는다','안 되면 팔을 빼고 상대를 향해 돌아 무릎을 넣는다']::text[], array['끼인 오른팔은 팔꿈치를 굽혀 상대 허리 쪽으로 붙인다','내 왼손은 상대 허리띠나 등에 — 상대 무게를 당겨 흔든다','내 오른쪽으로 브릿지한 뒤 엉덩이는 왼쪽으로 뺀다','왼팔을 상대 얼굴에 펴서 밀지 않는다']::text[], array['상대 무게가 내 가슴 위로 높이 올라오면 → 브릿지 이스케이프 (곁누르기)','브릿지로 상대가 등을 짚으면 → 백 테이크 (곁누르기 아래)','상대가 내 머리 쪽으로 몸을 기울이면 → 다리로 머리 걸어 빼기 (곁누르기 아래)','상대가 목 대신 언더훅으로 바꾸면 → 팔 빼고 가드 회복 (변형 곁누르기 아래)','위 방법이 막히면 → 곁누르기 이스케이프']::text[], array['왼팔로 상대 얼굴을 쭉 밀면 아메리카나 · 기무라를 당한다 → 왼손은 허리띠 · 등에 둔다','끼인 오른팔을 펴서 당기면 팔이 꺾인다 → 팔꿈치를 굽혀 몸 쪽으로 붙인다','브릿지 없이 엉덩이만 빼려 하면 안 빠진다 → 브릿지로 띄운 순간 엉덩이를 뺀다']::text[], array['파트너가 곁누르기로 가볍게 누르고, 나는 허리띠 잡고 브릿지 → 엉덩이 빼기를 10번']::text[] from public.positions where slug = 'kesa-gatame' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['브릿지와 새우빼기에 흔들리지 않고 자리부터 지킨다','상대 팔꿈치가 몸에서 떨어지면 하이 마운트로 올라간다','막는 손에 따라 초크와 암바를 번갈아 노린다']::text[], array['처음엔 엉덩이를 상대 명치 위에 낮게 두고 두 무릎으로 옆구리를 조인다','양손은 상대 머리 위쪽 바닥을 넓게 짚어 업파로 굴려질 때 버틴다','상대가 브릿지하면 내 발등을 상대 허벅지 밑에 걸고 엉덩이를 앞으로 민다','팔 공격은 상대 오른팔, 아메리카나만 상대 왼팔, 칼라 초크는 내 오른손이 상대 오른쪽 깃에 먼저']::text[], array['상대가 오른팔을 뻗어 내 가슴을 밀면 → 마운트 암바','상대가 팔꿈치를 붙이고 손으로 목만 지키면 → 크로스 칼라 초크 (마운트) 또는 에제키엘 초크','상대 왼손이 머리 옆 바닥에 놓이면 → 아메리카나 (마운트)','상대가 내 오른쪽으로 돌아누우면 → 테크니컬 마운트 또는 기프트 랩 → 백 테이크','상대가 팔꿈치로 내 무릎을 밀며 새우빼기하면 → 마운트 굳히기 (하이 마운트)']::text[], array['자리 잡기 전에 가슴 위로 높이 앉으면 업파 한 번에 뒤집힌다 → 처음엔 명치 위에 낮게 앉는다','짚은 손을 상대 몸 가까이 두면 상대가 팔을 묶어 굴린다 → 손은 머리 위쪽에 넓게 짚는다','누르고만 있으면 상대 프레임이 쌓여 하프가드가 된다 → 팔꿈치가 떨어지는 순간 바로 팔이나 하이 마운트']::text[], array['상대는 업파와 엘보 이스케이프만 1분, 위는 공격 없이 따라가며 마운트 유지']::text[] from public.positions where slug = 'mount' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['목과 팔을 먼저 지켜 서브미션을 막는다','하프가드나 가드로 돌아온다','상대가 앞으로 쏠리면 업파로 뒤집는다']::text[], array['팔꿈치는 옆구리에 붙이고 손은 턱 앞에 둔다, 팔을 쭉 뻗어 가슴을 밀지 않는다','두 발바닥을 매트에 붙이고 무릎을 세워 언제든 브릿지할 준비','업파는 상대 오른팔과 오른발을 묶은 뒤 내 왼쪽 어깨 너머로 굴린다','엘보는 내 오른쪽으로 돌아누워 오른 팔꿈치를 무릎 쪽에 프레임하고 상대 왼다리를 감는다']::text[], array['상대가 앞으로 기울어 손을 짚으면 → 마운트 이스케이프 (업파)','상대가 낮게 무겁게 붙어 있으면 → 마운트 이스케이프 (엘보) 또는 힐 드래그 이스케이프','상대 오른손이 내 깃을 깊게 잡으면 → 크로스 칼라 초크 막기 (마운트 아래)','상대가 겨드랑이까지 올라오면 → 하이 마운트 프레임 이스케이프 또는 트랩 앤 롤 (하이 마운트)','상대가 테크니컬 마운트로 바꾸면 → 테크니컬 마운트 이스케이프']::text[], array['팔을 뻗어 상대 가슴을 밀면 암바가 들어온다 → 팔꿈치를 붙이고 팔뚝으로 상대 골반을 막는다','엎드려 등을 돌리면 백을 내준다 → 옆으로 눕더라도 무릎을 넣어 하프가드로 간다','힘으로 브릿지만 반복하면 금방 지친다 → 팔과 발을 묶은 뒤 한 번에 브릿지한다']::text[], array['혼자 업파와 엘보 이스케이프를 번갈아 10회씩','상대는 마운트 유지만, 아래는 1분 안에 하프가드까지 돌아오기']::text[] from public.positions where slug = 'mount' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['가슴을 등에 붙이고 훅과 시트벨트를 놓치지 않는다','손싸움에서 이겨 목을 연다','리어 네이키드 초크로 끝낸다']::text[], array['내 오른팔(조르는 팔)은 상대 오른 어깨 위, 왼팔은 왼 겨드랑이 밑, 두 손을 붙여 잡는다','가슴을 상대 등에 붙이고 내 머리는 상대 머리 오른쪽에 바짝 댄다','발등은 상대 허벅지 안쪽 깊이 걸고, 상대 배 앞에서 발목을 꼬지 않는다','눕는 방향은 언더훅 쪽인 내 왼쪽으로 함께 눕는다']::text[], array['상대 턱이 들려 목이 열리면 → 리어 네이키드 초크','상대가 두 손으로 내 조르는 팔을 막고 버티면 → 보우 앤 애로우 초크 또는 암바 (백)','상대가 손으로 내 훅을 떼려 하면 → 바디 트라이앵글','상대가 목만 지키고 팔을 높이 들면 → 백 → 크루시픽스','상대가 등을 바닥에 붙이며 돌아누우면 → 백 → 마운트 (상대가 등을 바닥에 붙일 때)']::text[], array['상대 배 앞에서 발목을 꼬면 상대가 다리로 내 발목을 꺾는다 → 훅을 걸거나 바디 트라이앵글로 잠근다','뒤로 기대 가슴이 떨어지면 상대가 돌아선다 → 가슴과 엉덩이를 상대에게 붙인다','시트벨트를 일찍 풀고 목부터 노리면 상대 두 손에 막힌다 → 손싸움으로 팔을 내린 뒤 조른다']::text[], array['상대는 백 탈출만 시도, 위는 초크 없이 2분 동안 유지','시트벨트 → 손싸움 → 리어 네이키드 초크 세팅을 천천히 10회']::text[] from public.positions where slug = 'back-control' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['목부터 지킨다','훅을 떼고 등을 바닥 쪽으로 내려온다','돌아서 상대를 마주 보고 가드나 위로 간다']::text[], array['턱을 당기고 두 손으로 상대 오른 손목(조르는 팔)을 잡아 아래로 끌어내린다','조르는 팔 쪽인 내 오른쪽 어깨를 바닥에 붙이며 미끄러져 내려간다','상대 오른발 훅을 떼고 상대 오른다리를 넘어 내 왼쪽으로 돌아선다','엎드리지 말고 등을 상대 가슴 쪽, 바닥 쪽으로 기댄다']::text[], array['상대가 시트벨트로 목을 노리면 → 핸드 파이팅 (백 아래)','목을 지킨 뒤 상대 오른발 훅이 느슨하면 → 백 이스케이프 또는 숄더 워크 이스케이프','상대 훅이 하나 빠지면 → 돌아서 마주 보기 (백 아래)','상대가 바디 트라이앵글을 걸면 → 바디 트라이앵글 빠져나오기 또는 바디 트라이앵글 빠져나오기 (하프가드로)','상대가 다리 없이 시트벨트만 잡으면 → 시트벨트 빠져나오기']::text[], array['언더훅 쪽인 내 왼쪽으로 빠지면 상대가 다시 올라탄다 → 조르는 팔 쪽인 오른쪽 어깨로 내려간다','목을 비워 두고 손으로 훅부터 떼면 바로 초크가 들어온다 → 목을 지킨 다음 훅','앞으로 엎드리면 상대가 납작하게 눌러 버린다 → 등을 바닥 쪽으로 기댄다']::text[], array['상대는 시트벨트만 잡고 조르려 하고, 아래는 30초 손싸움 반복','혼자 누워 오른쪽 어깨로 바닥을 걸어 내려가는 숄더 워크 10회']::text[] from public.positions where slug = 'back-control' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['아래가 가드로 돌아오거나 일어서지 못하게 무게로 누른다','시트벨트와 훅으로 백을 잡는다','백이 막히면 크루시픽스나 목 공격으로 바꾼다']::text[], array['상대 왼쪽 옆에서 가슴을 상대 등에 붙이고 엉덩이는 낮게 둔다','시트벨트는 내 오른팔이 상대 오른 어깨 위, 왼팔이 왼 겨드랑이 밑','첫 훅은 내 왼발로 상대 왼 허벅지 안쪽에 넣는다','무게를 너무 앞으로 싣지 말고 상대가 움직이는 쪽을 따라간다']::text[], array['상대가 웅크리고 버티면 → 터틀에서 백 테이크 또는 클락 초크','상대가 왼팔을 바닥에 뻗어 짚으면 → 크루시픽스 (터틀)','크루시픽스로 두 팔을 묶으면 → 초크 (크루시픽스) 또는 암바 (크루시픽스)','상대 머리가 들리고 목이 보이면 → 다스 초크 (터틀) 또는 길로틴 (터틀)','상대가 내 오른쪽으로 구르며 가드로 가려 하면 → 터틀 뒤집기 (사이드로)']::text[], array['앞으로 너무 쏠리면 싯아웃이나 구르기로 빠져나간다 → 가슴은 등에 대고 엉덩이는 뒤에 둔다','상체를 잡기 전에 훅부터 넣으면 쉽게 막힌다 → 시트벨트 먼저, 훅은 그다음','등 위로 높이 올라타면 상대가 일어선다 → 엉덩이를 상대 엉덩이에 붙이고 아래 훅부터']::text[], array['상대가 그랜비·일어서기·싯아웃 중 하나를 고르고, 위는 따라가 백이나 크루시픽스로 마무리']::text[] from public.positions where slug = 'turtle' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['목과 겨드랑이를 막아 훅과 시트벨트를 못 넣게 한다','멈추지 말고 가드로 돌아오거나 일어선다']::text[], array['팔꿈치를 무릎에 붙이고 턱을 당겨 틈을 없앤다','상대는 내 왼쪽에 있다, 왼 무릎과 왼 팔꿈치를 붙여 첫 훅과 크루시픽스를 막는다','가드 회복은 상대 반대편인 내 오른쪽으로 엉덩이를 빼거나 오른 어깨로 구른다','팔을 길게 뻗어 바닥을 짚지 않는다']::text[], array['상대가 내 왼쪽 옆에서 무게만 실으면 → 그랜비 롤 (가드 회복) 또는 싯아웃 (터틀 탈출)','상대가 내 왼 허벅지 안쪽에 훅을 넣으려 하면 → 터틀에서 훅 걷어내기','상대 무게가 가볍고 떨어져 있으면 → 터틀에서 일어서기','상대가 내 왼팔을 다리로 가두면 → 크루시픽스 빠져나오기','상대가 크랩 라이드로 두 발을 걸면 → 크랩 라이드 빠져나오기']::text[], array['팔꿈치와 무릎 사이가 벌어지면 훅과 시트벨트가 들어온다 → 붙여서 닫는다','터틀에서 쉬고 있으면 상대가 자리를 잡는다 → 곧바로 구르거나 일어선다','팔을 뻗어 짚으면 크루시픽스·기무라에 걸린다 → 팔꿈치를 몸에 붙인다']::text[], array['혼자 그랜비 롤을 좌우 10회','상대가 터틀 위에서 손만 얹고, 아래는 3초 안에 가드나 일어서기']::text[] from public.positions where slug = 'turtle' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['상대 머리를 낮게 눌러 일어서지 못하게 한다','길로틴·다스·아나콘다로 목을 노린다','막히면 상대 오른쪽 옆으로 돌아 백을 잡는다']::text[], array['내 오른팔로 상대 턱 밑을 감고 왼손으로 상대 오른쪽 삼두를 잡는다','가슴으로 상대 뒤통수와 등 위를 누르고 엉덩이는 뒤로 빼 스프롤','팔힘보다 몸무게로 누르고 팔은 마무리할 때 쓴다','돌아 들어갈 땐 내 왼쪽(상대 오른쪽 옆)으로 돈다']::text[], array['상대가 머리를 들고 일어서려 하면 → 길로틴 세팅 또는 하이 엘보 길로틴','상대가 웅크려 목을 숨기면 → 다스 초크 (프론트 헤드락) 또는 아나콘다 초크','상대가 옆으로 돌아 빠지려 하면 → 프론트 헤드락 → 백','상대가 오른팔을 바닥에 뻗어 짚으면 → 기무라 (프론트 헤드락)','아나콘다로 굴렸는데 안 조여지면 → 아나콘다 안 되면 사이드']::text[], array['머리만 잡고 삼두를 안 잡으면 상대가 굴러 빠진다 → 왼손으로 상대 오른쪽 삼두를 잡는다','엉덩이가 들리면 상대가 일어선다 → 엉덩이를 뒤로 빼고 가슴을 아래로','한 기술만 붙잡고 있으면 상대가 빠져나간다 → 상대가 막는 쪽을 보고 다음 기술로']::text[], array['상대는 무릎 꿇고 머리를 들려 하고, 위는 30초 스프롤로 누르기','다스 → 아나콘다 → 백 테이크를 천천히 순환 5회']::text[] from public.positions where slug = 'front-headlock' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['목을 지켜 초크를 막는다','머리를 빼고 자세를 세우거나 일어선다','깔려도 등을 내주지 않고 가드로 돌아온다']::text[], array['상대 오른팔(조르는 팔)이 내 왼쪽에 있다, 두 손으로 그 손목을 잡아 끌어내린다','턱을 당기고 머리를 들어 자세를 세운다, 이마를 매트에 박지 않는다','팔을 길게 뻗어 짚지 말고 팔꿈치를 몸에 붙여 다스에 팔이 걸리지 않게 한다','무릎을 너무 벌리지 말고 발을 몸 밑에 둬 언제든 일어설 준비']::text[], array['상대가 길로틴을 걸면 → 길로틴 방어','길로틴에 걸린 채 상대 가드 안이면 → 길로틴에서 가드 회복','상대가 다스를 걸면 → 다스 방어 또는 백 도어 이스케이프 (다스)','상대가 아나콘다를 걸면 → 아나콘다 방어','상대 무게가 앞으로 쏠리면 → 피크 아웃 (프론트 헤드락 탈출) 또는 프론트 헤드락 빠져나오기 (서서 돌기)']::text[], array['머리를 숙이고 버티기만 하면 다스와 아나콘다가 들어온다 → 손목 싸움 후 머리를 든다','팔을 뻗어 바닥을 짚으면 목과 팔이 같이 감긴다 → 팔꿈치를 몸에 붙인다']::text[], array['상대가 헤드락을 걸고, 아래는 손목 잡기 → 머리 들기 → 일어서기를 10회']::text[] from public.positions where slug = 'front-headlock' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'top', array['잡은 팔과 목을 놓치지 않게 자세부터 굳힌다','천천히 압력을 걸어 마무리하고 탭하면 바로 놓는다','막히면 이어지는 다음 기술로 바꾼다']::text[], array['암바: 내 오른발은 상대 왼 골반, 왼다리는 얼굴 위, 무릎을 모으고 엉덩이를 상대 오른 어깨에 붙인다, 상대 엄지는 위로','트라이앵글: 내 오른다리 상대 목 뒤, 왼 오금으로 잠그고 엉덩이를 내 왼쪽으로 빼 각도, 상대 머리를 당긴다','기무라: 내 왼손 상대 오른 손목, 오른팔로 8자 그립, 상대 팔꿈치를 몸에서 떼고 직각을 유지한다','오모플라타: 내 왼다리 상대 오른 어깨 위, 오른팔로 상대 허리를 감아 앞구르기를 막는다']::text[], array['암바에서 상대가 두 손을 깍지 끼고 버티면 → 암바 그립 풀기','암바에서 상대가 일어서 눌러 오면 → 암바 → 트라이앵글','암바에서 상대가 팔을 접어 빼면 → 암바 → 오모플라타 또는 암바 → 기무라','트라이앵글에서 상대가 자세를 세우면 → 트라이앵글 → 암바 또는 트라이앵글 → 오모플라타','오모플라타에서 상대가 앞으로 구르려 하면 → 오모플라타 → 스윕']::text[], array['엉덩이와 다리를 굳히기 전에 팔만 당기면 팔이 빠진다 → 엉덩이를 붙이고 다리로 누른 뒤 당긴다','암바에서 무릎이 벌어지면 상대가 일어나 눌러 온다 → 무릎을 모아 얼굴과 가슴을 누른다','확 꺾으면 상대가 다친다 → 천천히 압력을 올리고 탭하면 즉시 놓는다']::text[], array['암바 → 트라이앵글 → 오모플라타를 끊지 않고 천천히 10회 순환']::text[] from public.positions where slug = 'submission-control' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.position_notes (position_id, role, goals, keys, decisions, mistakes, drills) select id, 'bottom', array['다치기 전에 탭한다, 안전이 먼저','걸린 팔이 펴지지 않게, 목은 각도가 안 나오게 버틴다','자세를 되찾고 빠져나와 위로 간다']::text[], array['암바: 걸린 내 오른팔을 펴지 말고 두 손을 서로 잡아 버틴다','트라이앵글: 갇힌 오른팔 팔꿈치를 몸에 붙이고 등을 세운 뒤 상대 엉덩이 각도를 막는다','기무라: 내 오른손으로 내 띠나 바지를 잡고 팔꿈치를 몸에 붙인다','오모플라타: 어깨가 눌리기 전에 앞으로 구르거나 상대 쪽으로 무게를 싣는다']::text[], array['암바에 팔이 펴지기 직전이면 → 암바 방어 (팔 빼기) 또는 히치하이커 이스케이프','트라이앵글 각도가 아직 덜 나왔으면 → 트라이앵글 탈출 (자세 세우기) 또는 트라이앵글 스택 탈출','기무라 그립이 잡히면 → 기무라 방어 또는 기무라 되치기 (구르기)','오모플라타로 어깨가 눌리면 → 오모플라타 앞구르기 탈출 또는 오모플라타 스택 방어','정강이가 목 앞을 누르면 → 고고플라타 방어 (자세 세우기)']::text[], array['걸린 팔을 힘으로 확 빼면 다음 기술로 이어져 더 깊이 걸린다 → 자세를 먼저 세우고 뺀다','트라이앵글에서 팔만 빼려 하면 목이 더 조여진다 → 자세와 엉덩이 각도부터','참다가 탭이 늦으면 팔꿈치·어깨를 다친다 → 아프기 전에 일찍 탭한다']::text[], array['상대가 암바·트라이앵글을 천천히 걸고, 아래는 첫 방어 자세만 10회 반복']::text[] from public.positions where slug = 'submission-control' on conflict (position_id, role) do update set goals = excluded.goals, keys = excluded.keys, decisions = excluded.decisions, mistakes = excluded.mistakes, drills = excluded.drills;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('frames', '프레임', 'Frames', 'principle', '팔·다리 뼈를 버팀목처럼 세워 상대 무게를 막고 움직일 공간을 지키는 것', array['프레임은 팔뚝·손바닥·정강이를 뼈대처럼 세워 상대와 내 몸 사이에 받치는 버팀목','프레임이 없으면 상대 가슴이 내 가슴에 붙고, 숨 쉴 틈도 엉덩이 뺄 틈도 사라진다','팔을 쭉 밀지 말고 팔꿈치를 굽힌 채 뼈로 받친다 — 근육이 아니라 뼈에 무게가 실리는 느낌','상대 목·어깨·골반처럼 상대가 들어오려는 길목에 댄다','프레임으로 버틴 순간 바로 엉덩이를 빼거나 무릎을 넣는다 — 프레임은 막는 게 아니라 다음 움직임을 위한 준비','흔한 실수: 팔을 펴서 밀어내기 — 힘만 빠지고 팔이 펴진 채 잡혀 암바·기무라를 내준다']::text[], array['사이드 컨트롤 아래 — 내 오른팔뚝을 상대 목에, 왼손은 상대 골반에 대고 새우 뺄 틈을 만든다','마운트 아래 — 상대가 높게 올라오면 양 팔뚝으로 상대 골반을 받쳐 엘보 이스케이프를 시작한다','하프가드 아래 — 무릎 방패(니 실드)와 오른팔뚝 프레임으로 상대 가슴이 덮치지 못하게 한다']::text[], array['side-control','mount','half-guard','north-south']::text[], array['side-control-escape','frame-escape-from-high-mount','knee-shield-half-guard','frame-and-shrimp-from-s-mount','shrimp-hip-escape']::text[], array['hip-escape','distance','elbow-knee']::text[], 0) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('base', '베이스', 'Base', 'principle', '닿아 있는 손·무릎·발로 무게를 나눠 받쳐 넘어지지 않는 안정감', array['베이스는 바닥이나 상대에 닿은 손·무릎·발로 내 무게를 받쳐 균형을 지키는 것','베이스가 좁거나 한쪽에 쏠리면 상대가 살짝만 밀어도 스윕을 당하거나 뒤집힌다','밀려 오는 방향 쪽으로 손이나 다리를 넓혀 받친다 — 너무 넓으면 못 움직이고, 너무 좁으면 쓰러진다','엉덩이를 낮추고 머리를 무게 중심 위에 두면 적은 힘으로 버틴다','움직일 때도 받침점을 하나 떼면 바로 다른 하나를 새로 놓는다','흔한 오해: 베이스는 가만히 버티는 자세 — 실제로는 상대 움직임에 맞춰 계속 바꿔 놓는 것']::text[], array['마운트 위 — 상대가 브릿지하면 그 방향으로 손을 짚고 무릎을 넓혀 뒤집히지 않는다','클로즈드 가드 안 — 무릎을 넓게 벌리고 엉덩이를 낮춰 시저 스윕·힙 범프에 버틴다','스탠딩 — 발을 어깨너비로 엇갈려 서서 밀고 당겨도 한 발로 받칠 수 있게 한다']::text[], array['mount','closed-guard','standing','passing']::text[], array['mount-maintain','consolidate-mount','standing-stance','combat-base','closed-guard-basics']::text[], array['posture','kuzushi','pressure']::text[], 1) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('posture', '자세(포스처)', 'Posture', 'principle', '머리·등·엉덩이를 바르게 세워 힘을 쓰고 버틸 수 있게 하는 몸의 정렬', array['자세(포스처)는 머리·척추·골반이 한 줄로 서 있어 힘을 주고받을 수 있는 상태','가드 안에서 자세가 무너지면 상대가 머리를 끌어내려 초크·암바·스윕을 줄줄이 건다','가드 안에서는 머리를 들고 등을 펴고, 손은 상대 배·골반에 짚어 상체가 끌려가지 않게 한다','아래에서는 거꾸로 다리로 당기고 그립으로 머리를 끌어 상대 자세를 무너뜨린다','무너뜨렸으면 상대가 다시 세우기 전에 바로 공격이나 스윕으로 이어 간다','흔한 실수: 가드 안에서 팔을 상대 목 쪽으로 뻗어 밀기 — 오히려 팔이 잡혀 트라이앵글을 내준다']::text[], array['클로즈드 가드 안 — 머리를 들고 상대 배에 양손을 짚은 뒤 일어나 가드를 연다','클로즈드 가드 아래 — 다리로 당기며 상대 깃을 잡아 머리를 내 가슴 쪽으로 끌어내린다','오픈 가드 패스 — 허리를 세우고 엉덩이를 낮춰 상대 발이 내 엉덩이에 걸리지 않게 한다']::text[], array['closed-guard','open-guard','passing']::text[], array['posture-recovery','closed-guard-break-knee','standing-guard-break','open-guard-passing-posture','closed-guard-basics']::text[], array['base','head-position','grips']::text[], 2) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('hip-escape', '새우(힙 이스케이프)', 'Hip Escape / Shrimp', 'principle', '옆으로 누워 엉덩이를 상대에게서 빼내 다리를 다시 넣을 공간을 만드는 움직임', array['새우(힙 이스케이프)는 옆으로 돌아누워 발로 바닥을 밀고 엉덩이를 상대에게서 멀어지게 빼는 움직임','새우를 못 하면 깔린 자세에서 다리를 다시 넣을 길이 없어 계속 눌리기만 한다','먼저 팔 프레임으로 상대가 따라오지 못하게 막고, 몸을 옆으로 세운 뒤 엉덩이를 뺀다','어깨가 아니라 엉덩이가 멀어지는 느낌 — 뺀 자리로 무릎을 바로 끼워 넣는다','한 번에 크게 못 빠지면 작은 새우를 여러 번 이어서 조금씩 공간을 모은다','흔한 실수: 등을 바닥에 댄 채 새우하기 — 옆으로 서지 않으면 엉덩이가 거의 안 움직인다']::text[], array['사이드 컨트롤 아래 — 오른팔 프레임으로 버티고 엉덩이를 빼서 오른 무릎을 상대 배 앞에 넣는다','마운트 아래 — 상대 오른 무릎 쪽으로 새우를 쳐서 하프가드로 돌아온다(엘보 이스케이프)','오픈 가드 — 상대가 옆으로 돌아 들어오면 새우로 각도를 맞춰 발을 다시 세운다']::text[], array['side-control','mount','open-guard','half-guard']::text[], array['shrimp-hip-escape','mount-escape-elbow','side-control-escape','elbow-escape-from-3-4-mount','half-guard-recovery']::text[], array['frames','bridge','guard-retention']::text[], 3) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('bridge', '브릿지', 'Bridge', 'principle', '발과 어깨로 받쳐 엉덩이를 들어 올려 위 사람의 무게를 흔드는 움직임', array['브릿지는 발바닥과 어깨로 바닥을 밀어 엉덩이를 높이 들어 위에 있는 상대를 띄우는 움직임','브릿지 없이 새우만 하면 상대 무게가 그대로 실려 엉덩이가 꼼짝 안 한다','발을 엉덩이 가까이 붙이고 뒤꿈치로 밀어 위·대각선 방향으로 터뜨린다','상대가 손을 짚거나 무게가 뜨는 순간 바로 엉덩이를 빼거나(새우) 뒤집는다(우파)','한 번에 안 되면 브릿지 → 새우 → 브릿지로 작게 이어 간다','흔한 실수: 팔 잡힘 없이 그냥 위로만 들기 — 상대가 손을 짚어 버텨서 뒤집히지 않는다']::text[], array['마운트 아래 — 상대 오른팔과 오른발을 막고 내 왼쪽 어깨 너머로 브릿지해 뒤집는다(우파)','사이드 컨트롤 아래 — 브릿지로 상대 무게를 띄운 순간 엉덩이를 빼 무릎을 넣는다','곁누르기 아래 — 브릿지로 상대를 내 위로 실어 넘기며 탈출 각을 만든다']::text[], array['mount','side-control','kesa-gatame']::text[], array['mount-escape-upa','bridge-and-roll-from-side','bridge-escape-from-kesa','trap-and-roll-from-high-mount','bridge-escape-from-modified-mount']::text[], array['hip-escape','escape-basics','timing-windows']::text[], 4) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('underhook', '언더훅', 'Underhook', 'principle', '내 팔을 상대 겨드랑이 밑으로 넣어 등을 감싸 몸통을 조종하는 그립', array['언더훅은 내 팔을 상대 팔 아래 · 겨드랑이 밑으로 넣어 등이나 어깨뼈를 감는 것','언더훅을 가진 쪽이 상대를 들고 돌리고 기울일 수 있다 — 빼앗기면 내가 깔리거나 등을 내준다','팔을 깊게 넣어 손바닥을 상대 등에 붙이고, 내 어깨와 머리를 상대 가슴 쪽에 붙여 지킨다','팔꿈치가 벌어지면 상대가 다시 파고든다 — 팔꿈치를 몸 쪽으로 조여 놓는다','상대가 언더훅을 넣으려 하면 팔을 수영하듯 안쪽으로 돌려 넣어(퍼밍) 되찾는다','흔한 실수: 손만 겨드랑이에 걸쳐 두기 — 얕은 언더훅은 위저 한 번에 무너진다']::text[], array['하프가드 아래 — 내 오른팔을 상대 왼 겨드랑이 밑으로 넣어 상체를 세우고 도그파이트로 간다','클린치 — 양팔 언더훅 싸움(퍼밍)으로 안쪽을 차지해 테이크다운 기회를 만든다','하프가드 위 — 내 언더훅으로 상대 어깨를 바닥에 눌러 하프가드를 납작하게 만든다']::text[], array['half-guard','clinch','deep-half','side-control']::text[], array['half-guard-underhook','underhook-pummeling','dogfight-position','half-guard-back-take','flattened-half-guard']::text[], array['whizzer','inside-position','head-position']::text[], 5) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('crossface', '크로스페이스', 'Crossface', 'principle', '팔과 어깨로 상대 얼굴을 반대로 돌려 몸을 못 돌리게 묶는 위쪽 컨트롤', array['크로스페이스는 내 팔뚝과 어깨를 상대 턱 · 얼굴 앞으로 넘겨 상대 고개를 나를 등지는 방향으로 돌리는 것','머리가 돌아가면 몸통도 나 쪽으로 돌지 못한다 — 크로스페이스가 없으면 상대가 나를 향해 돌아 가드를 되찾는다','손으로 얼굴을 미는 게 아니라 어깨 무게를 팔뚝에 실어 상대 턱을 옆으로 누른다','반드시 엉덩이 쪽 컨트롤(언더훅·무릎 막기)과 함께 써야 위아래가 다 막힌다','훈련에서는 목·턱에 무게를 천천히 싣고, 상대가 탭하거나 멈추라 하면 바로 푼다','흔한 실수: 손바닥으로 얼굴 밀기 — 힘만 들고 상대가 고개를 돌려 빠져나간다']::text[], array['사이드 컨트롤 위 — 내 오른팔로 상대 머리를 감아 고개를 돌려 상대가 나 쪽으로 돌아눕지 못하게 한다','하프가드 위 — 크로스페이스와 언더훅으로 상대를 납작하게 눌러 다리를 빼 패스한다','도그파이트 — 상대가 일어나려 할 때 크로스페이스로 다시 눌러 앉힌다']::text[], array['side-control','half-guard','kesa-gatame','north-south']::text[], array['side-control-maintain','smash-pass','crossface-from-dogfight','crossface-to-combat-base','half-guard-top-control']::text[], array['shoulder-pressure','head-position','hip-pressure']::text[], 6) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('whizzer', '위저(오버훅)', 'Whizzer / Overhook', 'principle', '상대 언더훅 팔을 위에서 감아 눌러 언더훅의 힘을 빼는 방어 그립', array['위저(오버훅)는 상대가 넣은 언더훅 팔을 내 팔로 위에서 감싸 아래로 누르는 것','언더훅을 그냥 두면 상대가 등을 잡거나 나를 넘기는데, 위저가 그 길을 막는 첫 방어','팔을 상대 어깨 위로 깊게 감고, 겨드랑이를 조이며 아래 · 뒤로 무게를 싣는다','팔만으로는 못 버틴다 — 엉덩이를 상대에게서 빼서 각도를 만들고 발로 받쳐 베이스를 지킨다','버티는 동안 일어서기 · 스윕 · 기무라 같은 다음 동작을 준비한다 — 오래 버티기만 하면 결국 진다','흔한 실수: 엉덩이를 붙인 채 팔만 당기기 — 상대가 그대로 파고들어 백을 잡는다']::text[], array['하프가드 위 — 상대가 왼팔 언더훅을 넣으면 내 오른팔로 위저를 감고 엉덩이를 빼 백을 막는다','딥 하프가드 위 — 위저로 상대 상체를 눌러 스윕 각을 줄인다','클로즈드 가드 위 — 상대 오버훅 가드에 잡히면 팔 각도를 바꿔 위저 압박을 풀어낸다']::text[], array['half-guard','deep-half','clinch','closed-guard']::text[], array['whizzer','half-guard-whizzer-counter','whizzer-from-deep-half','break-overhook-guard','overhook-control-sweep']::text[], array['underhook','inside-position','base']::text[], 7) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('inside-position', '인사이드 포지션', 'Inside Position', 'principle', '내 팔·무릎·발을 상대 팔다리 안쪽에 먼저 넣어 길목을 차지하는 것', array['인사이드 포지션은 내 손·팔꿈치·무릎·발이 상대 팔다리보다 안쪽(몸통 쪽)에 있는 상태','안쪽을 가진 쪽이 거리와 방향을 정한다 — 바깥에 있으면 상대가 정한 거리를 따라갈 수밖에 없다','팔꿈치를 갈비뼈 가까이 붙여 상대 손이 안쪽으로 못 들어오게 막는다','빈틈이 보이면 팔이나 무릎을 수영하듯 안쪽으로 밀어 넣고(퍼밍), 머리 위치로 받쳐 지킨다','차지한 안쪽은 금방 빼앗기니 바로 다음 동작(스윕·패스·테이크다운)에 쓴다','흔한 오해: 언더훅만 인사이드 — 무릎 방패, 버터플라이 훅, 정강이 프레임도 모두 안쪽 싸움이다']::text[], array['클린치 — 퍼밍으로 양팔을 안쪽에 넣어 상대 팔을 바깥으로 밀어낸다','버터플라이 가드 — 내 양발 훅을 상대 허벅지 안쪽에 넣어 들어 올릴 준비를 한다','하프가드 아래 — 내 오른 무릎을 상대 몸통과 팔 사이에 끼워 무릎 방패를 세운다']::text[], array['clinch','butterfly-guard','half-guard','open-guard']::text[], array['underhook-pummeling','butterfly-guard','knee-shield-half-guard','shin-to-shin-guard','feet-on-hips-guard']::text[], array['underhook','elbow-knee','grip-fighting']::text[], 8) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('elbow-knee', '팔꿈치 · 무릎 붙이기', 'Elbow-Knee Connection', 'principle', '팔꿈치와 무릎을 붙여 몸통 옆 빈틈을 막아 패스와 팔 공격을 막는 것', array['팔꿈치 · 무릎 붙이기는 아래에 있을 때 오른 팔꿈치와 오른 무릎처럼 한 편의 팔꿈치와 무릎을 가깝게 모아 옆구리 틈을 닫는 것','이 틈이 벌어지면 상대가 무릎·어깨로 파고들어 패스하고, 떨어진 팔은 암바·기무라 표적이 된다','몸을 살짝 옆으로 세우고 팔꿈치를 갈비뼈에, 무릎을 가슴 쪽으로 당겨 붙인다','상대 무게가 이미 틈에 들어왔다면 억지로 무릎을 밀어 넣지 말고 엉덩이부터 빼서 길을 만든다','팔꿈치를 먼저 되찾고 무릎은 그다음 — 순서를 거꾸로 하면 팔이 다리 밑에 갇힌다','흔한 실수: 그립 잡으려 팔을 멀리 뻗기 — 뻗는 순간 그 쪽 틈이 열린다']::text[], array['사이드 컨트롤 아래 — 내 왼 팔꿈치를 갈비뼈에 붙여 상대가 팔을 빼 가지 못하게 막는다','하프가드 아래 — 무릎 방패와 오른 팔꿈치를 붙여 상대가 가슴을 덮지 못하게 한다','오픈 가드 — 상대가 옆으로 돌면 그쪽 무릎을 팔꿈치 쪽으로 당겨 패스 길을 닫는다']::text[], array['side-control','half-guard','open-guard','mount']::text[], array['knee-shield-retention','open-guard-retention','mount-escape-elbow','arm-extraction','knee-shield-half-guard']::text[], array['frames','inside-position','guard-retention']::text[], 9) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('distance', '거리 조절', 'Distance Control', 'principle', '다음에 할 동작에 맞게 상대와의 간격을 붙이거나 벌리는 것', array['거리 조절은 공격하려면 붙고, 막거나 빠지려면 떨어지는 식으로 상대와의 간격을 내가 정하는 것','거리를 상대가 정하면 원치 않는 그립을 잡히고 원치 않는 자세로 끌려간다','벌릴 때는 프레임과 발로 받치고 엉덩이를 빼서 만든다 — 팔로만 밀면 금방 닫힌다','붙일 때는 그립·훅·가슴 접촉으로 연결을 만든다','공간이 생기면 상대가 다시 닫기 전에 바로 다리를 넣거나 일어난다','흔한 오해: 먼 게 늘 안전 — 어중간한 거리에 오래 머무르는 게 가장 위험하다']::text[], array['오픈 가드 — 발을 상대 골반에 대어 거리를 지키다 상대가 들어오면 바로 스윕 그립을 잡는다','패스 — 상대 다리 밖에서 멀리 돌거나, 붙어서 엉덩이로 눌러 패스할지 거리를 먼저 고른다','스탠딩 — 상대 손이 닿지 않는 거리에서 움직이다 들어갈 때 한 번에 레벨을 바꿔 붙는다']::text[], array['open-guard','passing','standing','side-control']::text[], array['feet-on-hips-guard','technical-stand-up','shrimp-hip-escape','open-guard-retention','float-passing']::text[], array['frames','hip-escape','connection']::text[], 10) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('pressure', '압박(프레셔)', 'Pressure', 'principle', '몸무게를 정해진 곳에 실어 상대가 원하는 움직임을 못 하게 막는 힘', array['압박(프레셔)은 근육으로 꽉 누르는 게 아니라 내 몸무게를 상대의 특정 부위에 실어 움직임을 막는 것','압박이 없으면 상대가 숨 돌리고 프레임을 세워 금방 빠져나간다','막고 싶은 움직임을 먼저 정한다 — 돌아눕기는 머리·어깨, 새우는 골반을 누른다','무릎이나 발끝으로 받쳐 베이스를 남긴 채 무게를 싣는다 — 다 실으면 브릿지에 뒤집힌다','자세를 바꿀 때도 접촉을 끊지 말고 무게를 옮겨 실어 상대가 틈을 못 찾게 한다','흔한 실수: 팔에 힘을 꽉 주고 버티기 — 금방 지치고 상대는 무게를 거의 못 느낀다']::text[], array['사이드 컨트롤 위 — 가슴을 상대 가슴에 붙이고 발끝으로 받쳐 무게를 실어 새우를 막는다','하프가드 위 — 어깨로 상대 얼굴을 누르고 엉덩이를 낮춰 다리를 빼는 동안 납작하게 묶는다','패스 — 상대 다리를 눌러 놓은 채 가슴으로 무게를 옮겨 실어 가며 사이드로 넘어간다']::text[], array['side-control','half-guard','passing','mount']::text[], array['side-control-maintain','pressure-pass','smash-pass','body-lock-pass','mount-maintain']::text[], array['shoulder-pressure','hip-pressure','base']::text[], 11) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('shoulder-pressure', '어깨 압박', 'Shoulder Pressure', 'principle', '어깨로 상대 턱·가슴에 무게를 실어 상체를 돌리지 못하게 묶는 압박', array['어깨 압박은 내 어깨를 상대 턱 옆이나 가슴에 대고 몸무게를 실어 상체를 묶는 것','상체가 묶이면 상대가 나 쪽으로 돌아눕거나 팔 프레임을 세우지 못한다','손이 아니라 몸통·엉덩이에서 무게를 어깨로 전달한다 — 뼈를 일자로 세워 받치면 오래 버틴다','어깨로 상체를, 엉덩이나 무릎으로 하체를 같이 막아야 새우까지 막힌다','훈련에서는 목을 비틀지 말고, 상대가 돌면 따라서 어깨 각도를 바꾼다','흔한 실수: 어깨만 들이밀고 엉덩이가 붕 떠 있음 — 무게가 안 실리고 쉽게 뒤집힌다']::text[], array['사이드 컨트롤 위 — 내 오른 어깨를 상대 턱 옆에 대어 고개를 돌리고 가슴 압박을 유지한다','하프가드 위 — 어깨로 상대 얼굴을 눌러 납작하게 만든 뒤 무릎을 빼 패스한다','아래에서 볼 때 — 상대 어깨가 들어오기 전에 팔뚝 프레임을 목 쪽에 세워 길을 막는다']::text[], array['side-control','half-guard','mount','north-south']::text[], array['side-control-maintain','smash-pass','arm-triangle','arm-triangle-from-half-top','half-guard-top-control']::text[], array['crossface','hip-pressure','pressure']::text[], 12) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('hip-pressure', '엉덩이 · 허리 압박', 'Hip Pressure', 'principle', '엉덩이를 낮추고 상대 골반에 붙여 새우·브릿지를 못 하게 막는 압박', array['엉덩이 · 허리 압박은 내 엉덩이를 낮게 붙여 상대 골반과 다리 움직임을 묶는 것','골반이 자유로우면 상대가 새우로 빠지거나 무릎을 넣어 가드를 되찾는다','먼저 상대 골반과의 틈을 없앤 뒤, 엉덩이를 바닥 쪽으로 떨어뜨려 무게를 싣는다','상대가 브릿지하거나 돌면 엉덩이 각도를 바꿔 따라가되 베이스는 남겨 둔다','상체 쪽 컨트롤(크로스페이스·언더훅)과 짝을 맞춰야 위아래가 다 막힌다','흔한 실수: 엉덩이를 높이 든 채 상체로만 누르기 — 밑에 공간이 생겨 무릎이 들어온다']::text[], array['패스 — 상대 다리를 누르고 엉덩이를 낮춰 붙이며 무릎을 썰어 넘어간다(니 슬라이스)','사이드 컨트롤 위 — 엉덩이를 낮추고 무릎으로 상대 골반을 막아 새우를 끊는다','하프가드 위 — 엉덩이를 뒤로 빼지 말고 붙여 눌러 상대 무릎 방패를 접는다']::text[], array['passing','side-control','half-guard','mount']::text[], array['knee-slice-pass','pressure-pass','body-lock-pass','double-under-pass','side-control-maintain']::text[], array['pressure','shoulder-pressure','crossface']::text[], 13) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('kuzushi', '기울이기(쿠즈시)', 'Kuzushi / Off-balancing', 'principle', '상대 무게를 받쳐 줄 손발이 없는 쪽으로 옮겨 균형을 무너뜨리는 것', array['상대 체중을 손 · 발 · 무릎이 받쳐 주지 못하는 방향으로 옮기는 것','균형이 멀쩡한 상대에게 스윕 · 테이크다운을 걸면 힘으로 밀어붙이는 싸움이 된다','먼저 상대가 어디를 짚고 서 있는지 보고, 짚을 데가 없는 방향을 고른다','그 방향으로 짚으려고 나올 손이나 발을 그립 · 훅으로 먼저 묶어 둔다','당기는 손과 엉덩이 · 다리 움직임을 한 박자에 같이 쓴다','흔한 실수: 상대가 버티고 있는 정면으로만 밀다가 힘만 빠진다']::text[], array['클로즈드 가드 — 내 왼손으로 상대 오른 소매를 잡아 오른손을 못 짚게 하고 그쪽으로 넘기는 시저 스윕','버터플라이 가드 — 상대 무게를 내 쪽으로 끌어와 엉덩이를 띄운 뒤 훅으로 들어 넘긴다','스탠딩 — 상대가 한 발에 무게를 실은 순간 그 발을 쓸어 넘어뜨린다']::text[], array['closed-guard','butterfly-guard','standing','open-guard']::text[], array['scissor-sweep','hip-bump-sweep','butterfly-sweep','o-uchi-gari','deashi-harai']::text[], array['posts','base','timing-windows']::text[], 14) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('angle', '각도 잡기', 'Dominant Angles', 'principle', '상대 정면을 피해 비스듬한 자리를 잡아 공격 길을 여는 것', array['상대의 가장 강한 방어선인 정면에서 벗어나 비스듬한 자리를 잡는 것','정면에 마주 붙어 있으면 상대 두 팔 · 두 다리가 모두 나를 막는다','엉덩이를 빼서 몸 방향을 틀면 상대 팔다리 일부만 상대하면 된다','각을 만든 뒤 그립 · 훅으로 상대가 다시 정면으로 돌아오지 못하게 잡는다','각이 생기면 바로 공격한다 — 머뭇거리면 상대가 다시 정면을 맞춘다','흔한 오해: 정면으로 힘껏 밀어붙이는 게 더 빠르다고 생각한다']::text[], array['클로즈드 가드 — 엉덩이를 빼서 몸을 틀어야 암바 · 트라이앵글이 깊게 들어간다','패스 — 상대 무릎 정면이 아니라 옆으로 돌아 들어가 니 슬라이스 · 토레안도를 건다','백 컨트롤 — 상대 등 뒤에 비스듬히 붙어야 초크 팔이 목 밑으로 들어간다']::text[], array['closed-guard','passing','back-control']::text[], array['closed-guard-hip-angle','closed-guard-armbar','triangle-choke','knee-slice-pass','toreando-pass']::text[], array['hip-escape','kuzushi','inside-position']::text[], 15) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('head-position', '머리 위치', 'Head Position', 'principle', '내 머리와 상대 머리를 어디 두느냐로 균형과 누르기가 달라진다', array['내 머리를 어디 두는지, 상대 머리를 어느 쪽으로 보내는지 둘 다를 말한다','머리가 가는 쪽으로 몸이 따라간다 — 머리를 뺏기면 자세도 같이 뺏긴다','위에 있을 때: 내 머리를 낮고 가깝게 붙여 그 무게로 상대를 누른다','상대 얼굴을 상대 엉덩이가 도는 방향과 엇갈리게 돌려 두면 상대가 몸을 돌리지 못한다','아래에 있을 때: 턱을 당기고 머리를 상대 가슴 쪽에 붙여 납작하게 눌리지 않게 한다','흔한 실수: 목 힘으로만 버티거나 상대 목을 억지로 비틀어 다치게 한다']::text[], array['사이드 컨트롤 위 — 내 오른팔 크로스페이스로 상대 얼굴을 상대 왼쪽으로 돌려 새우빼기를 막는다','클로즈드 가드 위 — 머리를 세우고 허리를 펴야 끌려 내려가지 않는다','하프가드 아래 — 머리를 상대보다 낮게 넣고 언더훅을 잡아야 깔리지 않는다']::text[], array['side-control','closed-guard','half-guard','standing']::text[], array['side-control-maintain','posture-recovery','half-guard-underhook','collar-tie']::text[], array['crossface','posture','pressure']::text[], 16) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('grips', '그립', 'Grips', 'principle', '손으로 상대 몸이나 도복을 잡아 움직임과 거리를 조절하는 것', array['손으로 소매 · 깃 · 바지 · 손목 · 목 뒤 등을 잡아 상대와 이어지는 것','그립 없이 기술을 쓰면 상대가 그냥 빠져나가고, 상대 그립을 놔두면 내가 묶인다','잡기 전에 이 그립이 무엇을 막고 무엇을 열어 주는지 먼저 정한다','손가락 끝보다 손바닥 · 손목으로 감아 잡고, 팔꿈치를 몸 쪽에 붙여 힘을 싣는다','자세가 바뀌면 그 자리에 맞는 그립으로 갈아 잡는다','흔한 실수: 아무거나 꽉 쥐고 버티다가 팔뚝이 먼저 터진다']::text[], array['클로즈드 가드 — 상대 깃과 소매를 잡아 자세를 무너뜨리고 짚을 팔을 묶는다','스파이더 · 라쏘 — 두 소매를 잡고 발로 팔을 밀어 거리를 지킨다','백 컨트롤 — 시트벨트 그립으로 상대 상체를 내 가슴에 붙여 둔다']::text[], array['closed-guard','spider-lasso','back-control','clinch']::text[], array['seat-belt-control','collar-sleeve-guard','cross-collar-choke-guard','grip-fighting']::text[], array['grip-fighting','connection','energy-conservation']::text[], 17) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('grip-fighting', '손싸움(그립 파이팅)', 'Grip Fighting', 'principle', '내 그립은 먼저 잡고 상대 그립은 못 잡게 하는 손의 싸움', array['내가 원하는 그립을 먼저 잡고, 상대의 위험한 그립은 자리 잡기 전에 떼는 싸움','손싸움에서 지면 상대 그립에 끌려다니며 내 기술은 시작도 못 한다','손을 쉬지 않고 움직이며 상대 손목 안쪽 자리를 먼저 차지한다','그립을 뗄 때는 두 손으로 상대 손 하나를 잡고, 엄지와 손가락 사이 열린 쪽으로 끊는다','손만 쓰지 말고 엉덩이 · 발을 같이 움직여 각을 바꾸며 뗀다','흔한 실수: 상대 그립을 그대로 둔 채 내 그립부터 잡으려 한다']::text[], array['클린치 — 상대 깃 그립을 먼저 떼고 내 칼라 타이를 잡는다','클로즈드 가드 위 — 상대 깃 그립을 두 손으로 떼어 내야 자세를 세울 수 있다','백 컨트롤 아래 — 목으로 오는 초크 손을 두 손으로 잡아 떼어 낸다']::text[], array['clinch','standing','closed-guard','back-control']::text[], array['grip-fighting','grip-break','grip-break-and-face','hand-fighting-from-back','armbar-grip-break']::text[], array['grips','inside-position','posture']::text[], 18) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('hooks', '훅', 'Hooks', 'principle', '팔이나 발을 갈고리처럼 걸어 상대를 따라가고 들어 올리는 연결', array['발등 · 정강이 · 팔을 휘어서 상대 다리나 겨드랑이에 거는 연결','훅이 없으면 상대가 움직일 때 놓치고, 들어 올리는 스윕도 걸리지 않는다','발로 걸 때는 발목을 세워 발등을 갈고리처럼 만들어야 쉽게 안 빠진다','훅을 딱딱하게 고정하지 말고 상대가 움직이는 대로 따라가며 걸려 있게 한다','훅 하나에 상체 그립 하나를 짝지어 쓴다','흔한 실수: 훅이 빠졌는데 다시 걸지 않고 다른 걸 하다가 패스당한다']::text[], array['버터플라이 가드 — 내 두 발등을 상대 허벅지 안쪽에 걸어 들어 넘긴다','백 컨트롤 — 두 발을 상대 허벅지 안쪽에 걸어 몸이 빠져나가지 못하게 한다','하프가드 아래 — 언더훅 팔로 상대 등을 감아 밑으로 파고든다']::text[], array['butterfly-guard','back-control','half-guard','x-guard']::text[], array['butterfly-sweep','hook-sweep','back-control-maintain','half-guard-underhook','x-guard-sweep']::text[], array['connection','underhook','guard-retention']::text[], 19) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('wedges', '쐐기(웨지)', 'Wedges', 'principle', '무릎 · 정강이 · 팔꿈치를 틈에 끼워 공간을 지키고 압박 길을 막는 것', array['상대와 나 사이 틈에 무릎 · 정강이 · 팔꿈치를 끼워 넣어 버티는 것','틈을 비워 두면 상대가 그 길로 몸을 붙여 나를 납작하게 누른다','틈이 생긴 순간, 상대가 움직이는 도중에 바로 끼운다','막고 싶은 방향을 향해 비스듬히 세우고 팔꿈치 · 엉덩이로 받쳐 무너지지 않게 한다','쐐기로 번 공간은 새우빼기 · 가드 회복에 바로 쓴다','흔한 실수: 쐐기를 끼우고 가만히 있다가 상대가 돌아 넘어와 눌린다']::text[], array['하프가드 아래 — 무릎을 상대 배 앞에 비스듬히 세운 니 실드로 눌림을 막는다','사이드 컨트롤 아래 — 팔꿈치 · 무릎을 상대 엉덩이 앞 틈에 끼우고 가드로 돌아온다','패스 — 상대 다리 사이에 내 무릎을 끼워 넣어 니 슬라이스 길을 연다']::text[], array['half-guard','side-control','passing','open-guard']::text[], array['knee-shield-half-guard','knee-shield-retention','side-control-escape','knee-slice-pass','shin-shield-recovery']::text[], array['frames','elbow-knee','guard-retention']::text[], 20) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('posts', '포스트(손 · 발 짚기)', 'Posts', 'principle', '손 · 발 · 머리를 바닥에 짚어 넘어지지 않게 받치는 것', array['몸이 기울 때 손 · 발 · 무릎 · 머리로 바닥을 짚어 받치는 것','짚을 곳이 없으면 작은 힘에도 스윕 · 테이크다운으로 넘어간다','쓰러지는 방향 쪽으로 바로 짚는다 — 생각하기 전에 몸이 먼저 나와야 한다','팔로 짚을 때는 어깨 · 팔꿈치 · 손목이 일자로 서야 무너지지 않는다','공격할 때는 반대로 상대가 짚을 손 · 발을 먼저 잡아 묶어 둔다','흔한 실수: 상대 가드 안에서 손을 바닥에 길게 짚었다가 그 팔로 기무라를 당한다']::text[], array['클로즈드 가드 위 — 스윕으로 넘어가는 쪽 발을 넓게 짚어 버티고, 손은 짚자마자 거둔다','버터플라이 가드 — 내 오른팔로 상대 왼팔을 감아 묶고 상대 왼쪽으로 넘긴다','마운트 아래 — 상대 오른팔 · 오른발을 묶고 내 왼쪽 어깨 너머로 브리지해 넘긴다']::text[], array['closed-guard','butterfly-guard','mount','standing']::text[], array['mount-escape-upa','butterfly-sweep','hip-bump-sweep','kimura-guard']::text[], array['base','kuzushi','frames']::text[], 21) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('connection', '연결(커넥션)', 'Connection', 'principle', '그립 · 훅 · 몸 접촉으로 상대 움직임을 느끼고 조종하는 것', array['그립 · 프레임 · 훅 · 몸 접촉으로 상대와 이어져 있는 상태','연결이 끊기면 상대가 자유롭게 움직이고 나는 늘 한 박자 늦게 따라간다','연결마다 할 일을 정한다 — 이 손은 거리를 지키고, 이 발은 엉덩이를 묶는다','손 · 팔 연결 하나와 발 · 무릎 · 엉덩이 연결 하나를 같이 둔다','상대 연결부터 끊고 내 연결을 만들고, 역할이 끝난 연결은 놓고 다음으로 바꾼다','흔한 실수: 아무 데나 붙어 있기만 하고 정작 아무것도 막지 못한다']::text[], array['오픈 가드 — 두 발은 상대 엉덩이에, 두 손은 소매에 둬 거리와 방향을 같이 조절한다','니 온 밸리 — 무릎 압박과 깃 그립을 이어 둬 상대가 움직이는 대로 따라간다','백 컨트롤 — 시트벨트와 두 훅을 같이 유지해 상대가 돌아 나가지 못하게 한다']::text[], array['open-guard','knee-on-belly','back-control','de-la-riva']::text[], array['feet-on-hips-guard','open-guard-retention','seat-belt-control','de-la-riva-guard']::text[], array['grips','hooks','frames']::text[], 22) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('position-before-submission', '포지션 먼저, 서브미션은 나중', 'Position Before Submission', 'principle', '서브미션보다 먼저 확실한 자리와 누르기를 만든다', array['상대를 충분히 묶어 둔 다음에야 서브미션을 건다는 원칙','자리가 불안한데 서브미션부터 던지면 실패할 때 자리까지 잃고 뒤집힌다','먼저 상대가 도망갈 길인 엉덩이 · 팔 · 머리를 막았는지 확인한다','서브미션을 거는 동안에도 무게와 베이스는 그대로 유지한다','서브미션이 안 되면 미련 없이 놓고 자리부터 다시 잡는다','흔한 오해: 서브미션만 노리는 게 빠르다 — 실제로는 좋은 자리가 서브미션을 쉽게 만든다']::text[], array['마운트 — 엉덩이를 낮추고 상대 팔을 정리한 뒤 암바 · 초크로 간다','사이드 컨트롤 — 크로스페이스 · 언더훅을 먼저 잡고 기무라 · 아메리카나를 건다','백 컨트롤 — 시트벨트와 훅을 고정한 뒤 리어 네이키드 초크를 건다']::text[], array['mount','side-control','back-control']::text[], array['consolidate-mount','mount-maintain','side-control-maintain','back-control-maintain','mount-armbar']::text[], array['positional-hierarchy','submission-chain','attack-with-fallback']::text[], 23) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('positional-hierarchy', '포지션 서열', 'Positional Hierarchy', 'principle', '어느 자리가 더 유리한지 순서를 알고 한 칸씩 올라가는 것', array['포지션마다 누가 더 잘 누르고 공격하고 빠져나가기 쉬운지로 매긴 순서','순서를 모르면 좋은 자리를 버리고 나쁜 자리로 가거나 쓸데없이 힘을 쓴다','대략 백 컨트롤 · 마운트가 가장 좋고, 그다음 니 온 밸리 · 사이드 컨트롤, 가드는 그 아래다','아래에 있으면 먼저 서브미션 · 압박 같은 위험부터 줄이고 그다음 한 칸 올라간다','위로 옮겼으면 새 자리를 확실히 고정한 뒤에야 올라갔다고 친다','흔한 오해: 순서는 절대 규칙이다 — 상대와 상황에 따라 낮은 자리가 더 나을 때도 있다']::text[], array['사이드 컨트롤 — 마운트로 갈 틈이 없으면 무리하지 말고 사이드를 지킨다','하프가드 아래 — 먼저 납작하게 눌리지 않게 막고, 그다음 언더훅으로 스윕 · 백을 노린다','터틀 — 백을 내주기 전에 가드로 돌아가거나 일어선다']::text[], array['back-control','mount','side-control','half-guard']::text[], array['side-to-mount','kob-to-mount','technical-mount-to-back','half-guard-recovery','turtle-to-guard']::text[], array['position-before-submission','transition','beginner-roadmap']::text[], 24) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('action-reaction', '작용 · 반작용', 'Action and Reaction', 'principle', '한 공격으로 상대 반응을 끌어내고, 그 반응이 만든 빈틈을 친다', array['먼저 진짜 위협을 걸어 상대가 막게 만들고, 막느라 생긴 빈틈을 공격하는 것','같은 기술만 되풀이하면 상대가 미리 막아 아무것도 걸리지 않는다','첫 공격은 진짜로 걸려야 한다 — 시늉만 하면 상대가 반응하지 않는다','상대가 밀면 당기고 당기면 민다 — 손 · 무게 · 자세가 한쪽에 쏠린 순간에 움직인다','공격을 바꾸는 동안에도 베이스와 그립은 놓지 않는다','흔한 실수: 반응을 보지 않고 미리 정한 순서대로만 기술을 던진다']::text[], array['클로즈드 가드 — 힙 범프 스윕을 막으려 상대가 손을 짚으면 그 팔로 기무라를 건다','스탠딩 — 상대를 밀면 상대가 밀어 버틴다 — 그 힘을 받아 당기며 업어치기를 건다','마운트 — 초크를 막으려 상대가 팔을 뻗으면 그 팔로 암바를 건다']::text[], array['closed-guard','standing','mount']::text[], array['hip-bump-sweep','kimura-guard','seoi-nage','mount-armbar','mount-cross-collar-choke']::text[], array['dilemma','predictable-responses','submission-chain']::text[], 25) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('dilemma', '양자택일 만들기(포크 어택)', 'Dilemmas / Fork Attacks', 'principle', '한 자리에서 두 공격을 함께 걸어 상대가 하나는 꼭 당하게 만드는 것', array['같은 그립 · 자리에서 두 공격을 함께 노려 상대가 둘 중 하나만 막게 하는 것','공격이 하나뿐이면 상대는 그것만 막으면 되니 오래 버틴다','두 공격이 같은 그립 · 자리에서 나오는지 먼저 확인한다 — 그립을 바꾸면 틈이 생긴다','두 공격 모두 진짜로 위협적이어야 상대가 고민한다','상대가 어느 쪽을 막는지 몸으로 느끼고 열린 쪽으로 바로 바꾼다','흔한 실수: 막힌 공격을 끝까지 고집하다가 열린 두 번째 공격을 놓친다']::text[], array['클로즈드 가드 — 힙 범프로 밀면 상대가 손을 짚는다 — 짚으면 그 팔에 기무라, 안 짚으면 그대로 넘긴다','마운트 — 크로스 칼라 초크를 막으려 팔을 들면 암바, 팔을 붙이고 버티면 초크를 끝까지 조인다','백 컨트롤 — 리어 네이키드 초크를 막느라 두 손이 목에 붙으면 팔을 잡아 암바로 바꾼다']::text[], array['closed-guard','mount','back-control']::text[], array['hip-bump-sweep','kimura-guard','mount-cross-collar-choke','mount-armbar','armbar-from-back']::text[], array['action-reaction','submission-chain','attack-with-fallback']::text[], 26) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('submission-chain', '서브미션 연결', 'Submission Chains', 'principle', '첫 서브미션을 막는 상대 반응을 이용해 다음 서브미션으로 잇는 것', array['한 서브미션이 막히면 상대가 막은 모양을 보고 다음 서브미션으로 넘어가는 흐름','하나만 걸고 막히면 끝나는 공격은 상대에게 숨 돌릴 시간을 준다','첫 공격은 상대가 진짜로 막아야 할 만큼 깊게 건다','다음 공격은 미리 정하지 말고 상대가 실제로 한 방어를 보고 고른다','넘어가는 동안 다리 · 그립 같은 핵심 연결은 놓지 않고, 안 되면 자리로 돌아간다','흔한 실수: 외운 순서대로만 던져서 상대 반응과 맞지 않는 기술을 건다']::text[], array['클로즈드 가드 — 암바를 막으려 팔을 빼면 트라이앵글, 트라이앵글을 버티면 오모플라타로 잇는다','마운트 — 아메리카나를 막으려 상대가 팔을 펴면 그 팔로 암바를 건다','서브미션 걸린 뒤 — 트라이앵글이 안 잠기면 같은 다리 자세에서 암바로 바꾼다']::text[], array['closed-guard','mount','submission-control']::text[], array['triangle-from-armbar','triangle-to-omoplata','triangle-to-armbar','switch-to-triangle','mount-americana']::text[], array['dilemma','action-reaction','position-before-submission']::text[], 27) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('submission-defense', '서브미션 방어 순서', 'Submission Defense', 'principle', '걸리기 전에 막고, 걸리면 상대가 잡은 조건을 하나씩 풀고, 늦으면 탭하는 순서', array['상대가 조르기 · 관절기를 끝내려면 그립 · 각도 · 고립이 필요하다 — 그걸 하나씩 빼앗는 일','순서를 모르면 팔을 빼다 목을 내주거나, 끝까지 버티다 다친다','1순위는 목: 턱을 당기고 손을 목 가까이 둔다 · 2순위는 팔꿈치: 갈비에 붙인다','손목이 잡히고 상대 몸이 옆으로 각을 틀면 공격 신호 — 그 그립부터 끊는다','팔이 이미 펴졌거나 목이 조여 오면 탈출보다 탭이 먼저','흔한 실수: 팔을 힘으로 잡아당기기만 한다 — 두 손을 맞잡아 버티며 몸 위치부터 바꾼다']::text[], array['서브미션 걸린 뒤 — 암바가 오면 두 손을 맞잡고 팔을 돌려 히치하이커로 빠진다','백 컨트롤 아래 — 두 손으로 목을 지키며 조르는 상대 오른팔 손목부터 끊는다','클로즈드 가드 위 — 두 팔을 함께 안에 두고 자세를 세워 트라이앵글 각을 안 준다']::text[], array['submission-control','back-control','closed-guard','front-headlock']::text[], array['armbar-defense','hitchhiker-escape','kimura-defense','guillotine-defense','triangle-escape-posture']::text[], array['prevention-over-cure','tap-safety','escape-basics']::text[], 28) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('escape-basics', '탈출의 기본 순서', 'Escape Fundamentals', 'principle', '깔렸을 때 목 · 팔 지키기 → 프레임 → 엉덩이 빼기 → 가드 되찾기 순서', array['사이드 · 마운트 · 곁누르기처럼 깔린 자리에서 빠지는 공통 순서','순서 없이 밀고 버둥대면 팔이 펴져 서브미션을 주고 힘만 빠진다','1 목과 팔꿈치를 몸에 붙여 공격받을 곳부터 닫는다','2 팔뚝 · 무릎으로 프레임을 세우고, 그 버팀목 덕에 생긴 틈으로 엉덩이를 뺀다(새우빼기 · 브릿지)','3 틈에 무릎을 넣어 가드를 만들고, 얻은 걸 지킨 채 다음 단계로 간다','흔한 실수: 팔을 쭉 펴서 상대를 밀어낸다 — 밀지 말고 버팀목을 세운 뒤 내가 움직인다']::text[], array['사이드 컨트롤 아래 — 상대가 내 오른쪽이면 왼 팔뚝은 상대 목, 오른손은 상대 엉덩이에 대고 새우빼기로 오른 무릎을 넣는다','마운트 아래 — 팔꿈치를 붙이고 브릿지로 상대를 흔든 뒤 팔꿈치 · 무릎 탈출로 하프가드를 만든다','곁누르기 아래 — 목을 먼저 지키고 브릿지와 엉덩이 빼기로 등을 바닥에서 뗀다']::text[], array['side-control','mount','kesa-gatame','north-south']::text[], array['side-control-escape','mount-escape-elbow','mount-escape-upa','escape-kesa-gatame','shrimp-hip-escape']::text[], array['frames','hip-escape','defense-under-pressure']::text[], 29) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('defense-under-pressure', '눌릴 때 버티기', 'Dealing with Pressure', 'principle', '위에서 체중으로 누를 때 숨 쉬며 버티고, 작게 틈을 모아 빠지는 법', array['상대 무게에 깔려 숨이 답답할 때 무너지지 않고 버티는 기술','당황해 한꺼번에 힘을 쓰면 금방 지치고, 그때 뻗은 팔로 서브미션을 준다','지킬 순서: 서브미션 막기 → 숨 쉬기 → 지금 자리 지키기 → 탈출','등을 바닥에 다 붙이지 말고 상대 쪽으로 살짝 옆으로 눕는다 — 눌리는 면이 줄어든다','상대가 자세를 바꾸려 무게를 옮기는 순간에 짧게 움직여 틈을 조금씩 모은다','흔한 실수: 계속 버둥댄다 — 쉴 땐 프레임으로 버티고, 움직일 땐 한 번에 짧게']::text[], array['사이드 컨트롤 아래 — 어깨로 얼굴을 누르면 턱을 당기고 옆으로 돌아 숨 쉴 틈을 만든다','하프가드 아래 — 납작하게 눌리면 아래 팔꿈치를 세워 프레임하고 옆으로 돌아 크로스페이스를 막는다','니 온 밸리 아래 — 무릎 압박에 숨이 막히면 두 손으로 무릎을 받치며 엉덩이를 빼낸다']::text[], array['side-control','half-guard','knee-on-belly','mount']::text[], array['side-control-escape','escape-shoulder-of-justice','knee-on-belly-escape']::text[], array['energy-conservation','escape-basics','frames']::text[], 30) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('guard-retention', '가드 리텐션', 'Guard Retention', 'principle', '상대가 다리를 넘으려 할 때 팔꿈치 · 무릎 · 엉덩이로 가드를 지키는 기술', array['패스가 끝나기 전에 몸통 앞을 다시 막아 가드를 지키는 일','놓치면 사이드 컨트롤로 깔려 탈출부터 다시 해야 한다','팔꿈치와 무릎 사이 틈을 닫는다 — 상대가 그 틈에 어깨 · 무릎을 넣으면 패스다','상대가 옆으로 돌면 엉덩이로 따라 돌아 늘 상대를 마주 본다','무릎이 바로 안 들어가면 팔꿈치 프레임 먼저, 새우빼기로 길을 낸 뒤 무릎을 넣는다','흔한 실수: 공격 그립만 붙잡고 있다 — 다리가 넘어가면 그립을 놓고 막는 쪽으로 바꾼다']::text[], array['오픈 가드 — 상대가 내 오른쪽으로 돌면 엉덩이를 돌려 따라가며 오른 무릎을 다시 안에 넣는다','하프가드 아래 — 니 실드(무릎 방패)를 세우고 그쪽 팔꿈치를 무릎에 붙여 크로스페이스를 막는다','패스 아래 — 레그 드래그로 다리가 넘어가면 프레임 후 새우빼기로 가드를 되찾는다']::text[], array['open-guard','half-guard','passing','butterfly-guard']::text[], array['open-guard-retention','knee-shield-retention','shin-shield-recovery','frame-and-shrimp-from-leg-drag','guard-recovery-from-combat-base']::text[], array['elbow-knee','layers-of-guard','guard-phases']::text[], 31) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('layers-of-guard', '가드의 층', 'Layers of Guard', 'principle', '상대가 내 몸통에 닿기 전 거쳐야 하는 막 — 발 · 정강이 · 무릎 · 팔', array['가드는 여러 겹의 막: 멀면 발 · 정강이, 가까우면 무릎, 마지막은 팔 프레임','막이 모두 걷히면 상대 가슴이 내 가슴에 붙고 패스가 끝난다','막 하나가 걷혀도 남은 막으로 버티면서 걷힌 막을 다시 세운다','거리에 맞는 막을 쓴다 — 이미 붙었는데 발부터 넣으려 하면 들어갈 길이 없다','막의 개수보다 ''이 막이 지금 무엇을 막고 있나''를 본다','흔한 실수: 치워진 발을 되찾으려 몸까지 뻗다가 남아 있던 프레임까지 잃는다']::text[], array['오픈 가드 — 발 하나가 치워지면 남은 발과 손 그립으로 거리를 지키며 다시 넣는다','하프가드 아래 — 니 실드가 접히면 팔을 안쪽에 두고 머리를 지키며 다시 세울 틈을 만든다','버터플라이 가드 — 훅이 빠지면 언더훅 · 팔꿈치로 버티며 훅을 다시 넣는다']::text[], array['open-guard','half-guard','butterfly-guard','passing']::text[], array['open-guard-retention','knee-shield-retention','butterfly-hook-recovery']::text[], array['guard-retention','guard-phases','distance']::text[], 32) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('passing-phases', '패스의 3단계', 'Phases of Passing', 'principle', '패스는 그립 풀기 → 다리 지나가기 → 눌러 고정하기 세 가지 일', array['1 내 다음 동작을 막는 그립 · 훅 하나를 푼다 — 전부 풀 필요는 없다','2 다리를 지나가며 상대 엉덩이와 돌아오는 무릎을 막는다','3 가슴을 붙여 고정하고, 상대 첫 탈출 시도를 버틴 뒤에 공격한다','하나라도 빠지면 다리를 넘고도 다시 가드에 갇힌다','패스가 막히면 ''세 일 중 어느 게 빠졌나''로 진단한다','흔한 실수: 다리를 넘자마자 서브미션부터 잡는다 — 고정이 먼저']::text[], array['데라히바 위 — 자세를 끄는 깃 그립과 다리 훅부터 처리하고 패스 방향을 정한다','하프가드 위 — 무릎을 빼는 동안 크로스페이스 · 언더훅으로 상체를 붙잡아 사이드로 간다','사이드 컨트롤 위 — 막 도착했다면 상대 새우빼기 한 번을 버텨야 패스 완료']::text[], array['passing','de-la-riva','half-guard','side-control']::text[], array['knee-cut-from-headquarters','over-under-pass','smash-pass']::text[], array['position-before-submission','guard-phases','crossface']::text[], 33) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('guard-phases', '가드의 3단계', 'Phases of Guard', 'principle', '가드 아래에선 붙잡기 · 흔들어 공격 · 지키기 중 지금 할 일을 고른다', array['붙잡기: 그립 · 발로 상대와 쓸모 있는 연결을 만든다','흔들기: 그 연결로 상대 균형을 깨 스윕 · 서브미션을 노린다','지키기: 다리가 넘어가려 하면 공격을 멈추고 막을 다시 세운다','지금 할 일을 잘못 고르면 공격하는 사이에 패스당한다','순서가 정해진 게 아니라, 매 순간 ''셋 중 지금 무엇인가''를 판단한다','흔한 실수: 원래 가드를 고집한다 — 그립이 다 풀렸으면 아무 가드라도 먼저 되찾는다']::text[], array['오픈 가드 — 앉아서 손목 그립과 발로 거리를 잡는 게 첫 일(붙잡기)','데라히바 — 훅과 그립이 잡히면 상대 무게를 흔들어 스윕을 시도(흔들기)','패스 아래 — 상대가 엉덩이 옆까지 오면 그립을 놓고 팔꿈치 · 무릎으로 막는다(지키기)']::text[], array['open-guard','de-la-riva','closed-guard','passing']::text[], array['open-guard-retention','recovery-from-failed-sweep']::text[], array['layers-of-guard','guard-retention','passing-phases']::text[], 34) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('transition', '전환 때 잃지 않기', 'Transition Management', 'principle', '자리를 옮기는 순간 잡은 걸 놓치지 않고, 막히면 돌아갈 길을 남기는 것', array['사이드 → 마운트, 마운트 → 백처럼 자리를 옮기는 사이가 가장 위험하다','그 틈에 상대가 빠지거나 뒤집어 버린다','옮기기 전에 상대 탈출을 막고 있는 컨트롤 하나는 끝까지 유지한다','도착하면 공격보다 먼저 균형(베이스)을 잡고 고정한다','상대가 길을 막으면 억지로 가지 말고 원래 자리로 돌아온다','흔한 실수: 크고 빠르게만 움직인다 — 둘 다 아무것도 안 잡은 시간이 길어진다']::text[], array['사이드 컨트롤 위 — 마운트로 갈 때 크로스페이스를 유지한 채 무릎을 배 위로 넘긴다','곁누르기 — 마운트나 사이드로 옮길 때 머리 · 팔 컨트롤을 놓지 않는다','마운트 위 — 상대가 등을 돌리는 순간을 기다렸다가 훅을 넣어 백으로 간다']::text[], array['side-control','kesa-gatame','mount','back-control']::text[], array['kesa-to-mount','kesa-to-side-control','side-control-to-kesa']::text[], array['base','attack-with-fallback','timing-windows']::text[], 35) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('chokes', '조르기 두 종류(혈관 · 기도)', 'Blood vs Air Chokes', 'principle', '목 옆 혈관을 누르는 조르기와 목 앞 숨길(기도)을 누르는 조르기의 차이', array['혈관 조르기: 목 양옆 혈관을 눌러 뇌로 가는 피를 막는다(리어 네이키드 · 트라이앵글 · 칼라 초크)','기도 조르기: 목 앞 숨길을 누른다 — 아프고 다치기 쉬워 연습에선 더 천천히','혈관 조르기는 짧은 시간에 기절할 수 있다 — 조여 오는 느낌이 오면 바로 탭','거는 쪽: 자리부터 잡고, 세게 쥐기보다 팔과 목 사이 틈을 없애고 각을 맞춘다','압력이 턱에 걸리거나 목을 꺾는 쪽으로 가면 멈추고 다시 맞춘다','흔한 실수: 턱 위로 팔을 감고 힘으로 쥔다 — 아프기만 하고 안 걸린다']::text[], array['백 컨트롤 — 리어 네이키드 초크: 팔꿈치를 상대 턱 밑 가운데로 보내고 가슴을 붙여 틈을 없앤다','클로즈드 가드 — 트라이앵글: 상대 목과 한쪽 팔을 다리로 감아 목 옆 혈관을 누른다','프론트 헤드락 — 길로틴: 팔 위치에 따라 숨길을 누를 수 있어 천천히 조인다']::text[], array['back-control','closed-guard','front-headlock','mount']::text[], array['rear-naked-choke','triangle-choke','cross-collar-choke-guard','guillotine-choke-finish','ezekiel-choke']::text[], array['tap-safety','head-position','position-before-submission']::text[], 36) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('joint-locks', '관절기 원리', 'Joint Lock Mechanics', 'principle', '관절을 원래 굽는 방향과 반대로 밀거나 비틀어 탭을 받는 원리', array['팔꿈치 · 무릎을 반대로 펴거나(암바 · 니바), 어깨를 비트는(기무라 · 아메리카나) 공격','힘이 아니라 지렛대: 관절 위아래를 붙잡고 관절 바로 뒤를 민다','관절 위(어깨 · 엉덩이)와 아래(손목 · 발목)를 함께 잡아야 상대가 돌려 빠지지 못한다','팔로 당기지 말고 엉덩이로 천천히 민다 — 연습 상대가 탭할 시간을 준다','흔한 실수: 각이 틀어진 채 확 꺾는다 — 안 걸리거나, 걸리면 탭 전에 다친다']::text[], array['마운트 — 암바: 무릎을 조이고 상대 엄지가 위를 보게 한 뒤 엉덩이를 천천히 든다','사이드 컨트롤 — 아메리카나: 상대 손목을 매트에 붙이고 팔꿈치를 들어 어깨를 비튼다','X 가드 — 스트레이트 앵클락: 발목을 겨드랑이에 끼고 몸을 젖힌다(허용 여부는 체육관 · 대회 규정을 확인)']::text[], array['mount','side-control','submission-control','x-guard']::text[], array['mount-armbar','armbar-finish','americana-side','kimura-finish','straight-ankle-lock']::text[], array['limb-isolation','tap-safety','submission-chain']::text[], 37) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('limb-isolation', '팔 · 다리 떼어 내기', 'Limb Isolation', 'principle', '공격할 팔 · 다리를 상대 몸통과 다른 팔다리의 도움에서 떼어 놓는 것', array['팔은 갈비 · 다른 팔 · 바닥에 기대 버틴다 — 그 받침을 하나씩 뺀다','떼지 않고 서브미션을 걸면 힘겨루기가 되고 결국 놓친다','손목만 잡지 말고 어깨(다리라면 엉덩이)까지 컨트롤한다','팔이 돌아갈 길목에 무릎 · 정강이 · 머리를 끼워 막는다','팔을 당기지 말고 내 몸을 그 팔 쪽으로 옮긴다','흔한 실수: 팔꿈치가 이미 갈비에 다시 붙었는데 계속 당긴다 — 놓고 자리부터 다시 잡는다']::text[], array['마운트 위 — 하이 마운트로 올라가 상대 팔꿈치를 갈비에서 떼고 암바로 간다','백 컨트롤 — 상대 오른팔을 내 다리로 눌러 두면 목을 지킬 손이 왼손만 남는다','터틀 · 크루시픽스 — 상대 팔을 내 다리로 감아 떼어 내고 기무라 · 암바를 노린다']::text[], array['mount','back-control','turtle','side-control']::text[], array['mount-armbar','armbar-from-crucifix','kimura-from-crucifix','armbar-on-free-arm','kimura-trap']::text[], array['elbow-knee','joint-locks','connection']::text[], 38) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('tap-safety', '탭 · 안전', 'Tapping and Safety', 'principle', '위험하면 일찍 탭하고, 상대가 탭하면 바로 놓는 약속', array['탭은 ''졌다 · 멈춰'' 신호: 손으로 상대 몸이나 매트를 여러 번 치거나 말로 ''탭''','늦은 탭은 팔꿈치 · 무릎 · 목을 다치게 하고 한동안 운동을 못 하게 만든다','손이 묶이면 발로 매트를 치거나 말로 알린다','거는 쪽: 천천히 조이고, 탭 · 소리 · 이상한 느낌이 오면 그 자리에서 바로 푼다','허용 기술(힐훅 · 목 꺾기 · 슬램 등)과 띠별 제한은 체육관 · 대회 규정을 확인','흔한 실수: ''아직 괜찮아'' 하고 버틴다 — 관절은 아프기 시작한 뒤 금방 다친다']::text[], array['서브미션 걸린 뒤 — 암바로 팔이 펴지기 시작하면 빠질 궁리보다 탭이 먼저','백 컨트롤 아래 — 초크가 깊게 들어와 머리가 멍해지기 전에 탭','스탠딩 — 던져질 땐 낙법으로 머리를 지키고, 주변 사람과 부딪힐 공간인지 살핀다']::text[], array['submission-control','back-control','standing']::text[], array['breakfall','armbar-defense']::text[], array['chokes','joint-locks','training-intensity']::text[], 39) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('beginner-roadmap', '화이트 벨트 길잡이', 'Beginner Roadmap', 'learning', '포지션 이름과 내 할 일부터 알고, 작은 기술 묶음 하나로 시작하기', array['지금 어느 포지션인지, 내가 위인지 아래인지부터 말할 수 있게 한다','처음부터 다 외우려 하면 아무것도 스파링에서 못 쓴다','코치와 묶음 하나를 고른다: 깔린 데서 탈출 1 · 가드 되찾기 1 · 스윕 1 · 패스 1','탭하는 법과 탭 받으면 바로 놓는 법은 첫날부터 익힌다','진도는 띠 · 서브미션 수가 아니라 ''프레임을 버텼나 · 첫 동작이 떠올랐나''로 본다','흔한 실수: 영상 속 마무리만 따라 한다 — 시작 자리(컨트롤)부터 배운다']::text[], array['사이드 컨트롤 아래 — 프레임과 새우빼기로 가드 되찾기 하나','클로즈드 가드 — 상대 자세 무너뜨리기와 기본 스윕 하나','마운트 — 아래에선 브릿지 탈출, 위에선 무게 실어 버티기']::text[], array['side-control','closed-guard','mount','back-control']::text[], array['side-control-escape','mount-escape-upa','shrimp-hip-escape','breakfall']::text[], array['positional-hierarchy','tap-safety','positional-sparring']::text[], 40) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('positional-sparring', '포지션 스파링', 'Positional Sparring', 'learning', '정한 자리에서 시작해 각자 목표를 이루면 다시 시작하는 짧은 스파링', array['시작 자리 · 그립 · 각자 목표(예: 위는 패스, 아래는 스윕)를 미리 정한다','자유 스파링에선 연습하고 싶은 자리에 몇 번 못 가지만, 여기선 그 자리를 계속 반복한다','목표를 이루거나 탭이 나오면 바로 처음 자리로 리셋','힘 세기는 배우는 기술에 맞춘다: 처음엔 가볍게, 익숙해지면 올린다','역할을 번갈아 하고, 라운드 사이 ''어디서 자꾸 막혔나'' 한 줄로 정리한다','흔한 실수: 목표 없이 이기려고만 한다 — 그러면 그냥 짧은 자유 스파링이 된다']::text[], array['사이드 컨트롤 — 아래는 가드 되찾기, 위는 고정 유지 또는 마운트','하프가드 — 아래는 스윕 · 백 잡기, 위는 패스','백 컨트롤 — 아래는 탈출, 위는 초크']::text[], array['side-control','half-guard','back-control','closed-guard']::text[], '{}'::text[], array['flow-rolling','training-intensity','beginner-roadmap']::text[], 41) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('flow-rolling', '흘러가는 롤링(플로우 롤)', 'Flow Rolling', 'learning', '이기려 하지 않고 서로 움직임을 주고받으며 천천히 이어 가는 롤링', array['둘이 같은 속도로 움직이며 넘기기 · 빠지기 · 걸기를 끊지 않고 이어 가는 연습 롤링','늘 세게만 하면 새 기술은 못 써 보고 다치기 쉽고, 쓰는 동작만 계속 쓰게 된다','시작 전에 "천천히, 걸리면 놓고 이어 가자"처럼 속도와 끝내는 방법을 말로 맞춘다','서브미션은 들어간 느낌까지만 잡고 꽉 조이지 않고 풀어 준 뒤 계속 움직인다','상대가 스윕 · 패스를 시도하면 막되 완전히 버티지 않고, 막혔다 풀렸다를 오가게 둔다','흔한 실수: 상대가 조금 세지면 나도 같이 세져서 결국 시합처럼 변해 버린다']::text[], array['하프가드 아래 — 언더훅 싸움을 서로 번갈아 이기며 스윕 들어가는 길을 여러 번 느껴 본다','사이드 컨트롤 — 위는 누르기를 바꾸고 아래는 프레임 · 쉬림프로 빠지며 자리를 계속 바꾼다','클로즈드 가드 — 자세 무너뜨리기 · 암바 · 트라이앵글 들어가는 길을 끝내지 않고 이어 본다']::text[], array['closed-guard','half-guard','side-control','mount']::text[], '{}'::text[], array['training-intensity','positional-sparring','energy-conservation']::text[], 42) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('training-intensity', '롤링 세기 고르기', 'Training Intensity', 'learning', '이번 판이 뭘 연습하는 판인지에 맞춰 속도와 버티는 정도를 정하는 것', array['세기는 하나가 아니라 속도 · 버티는 정도 · 써도 되는 공격 세 가지로 나뉜다','그냥 "살살 하자"만 말하면 사람마다 다르게 받아들여서 금방 세지거나 너무 헐렁해진다','새 동작은 상대가 거의 내어 주는 상태로 시작하고, 되면 막는 방법 하나만 더한다','"패스만 막기 · 스윕 나면 다시 시작"처럼 상대가 할 일을 말로 정해 두고 시작한다','둘 중 하나라도 속도를 못 따라가면 바로 멈추고 다시 정한다','흔한 오해: 천천히 하면 쉬운 판이다 — 느려도 그립을 안 주고 버티면 충분히 어렵다']::text[], array['하프가드 위 — 익숙한 패스를 먼저 협조로 연습한 뒤, 아래는 니 쉴드 되찾기만 허용한다','마운트 아래 — 위는 공격 없이 유지만, 아래는 정해 둔 이스케이프만 쓰기로 맞춘다','백 컨트롤 — 초크 시도 여부와 다시 시작하는 조건을 먼저 정하고 들어간다']::text[], array['half-guard','mount','back-control']::text[], array['knee-shield-retention','mount-escape-elbow']::text[], array['flow-rolling','positional-sparring','partner-diversity']::text[], 43) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('partner-diversity', '여러 상대와 하기', 'Training Partner Diversity', 'learning', '여러 사람과 해 봐야 내 기술이 어디서 상대 덕을 보고 있었는지 보인다', array['늘 같은 상대와만 하면 그 사람이 늘 하는 반응에 맞춘 기술만 늘어난다','새 상대에게 안 먹히면, 내 기술이 어떤 조건(앞으로 숙이기 · 팔 길이 · 속도)에 기대고 있었는지 드러난다','상대를 바꾸기 전에 "인사이드 지키기"처럼 확인할 질문 하나를 정해 둔다','졌을 때 몸집 · 띠 탓을 하기 전에 상대의 그립 · 자세 · 첫 방어가 뭐였는지 본다','익숙한 상대와는 고친 점을 다듬고, 새 상대와는 그게 언제 통하는지 시험한다','흔한 실수: 한 번 막히면 상대 · 기술 · 시작 자리를 한꺼번에 다 바꿔서 원인을 못 찾는다']::text[], array['클로즈드 가드 — 앞으로 숙이던 상대에겐 되던 스윕이 뒤로 앉는 상대에겐 안 되는 이유를 찾는다','하프가드 아래 — 팔이 긴 상대가 니 쉴드를 돌아 들어올 때 프레임 거리를 다시 맞춘다','마운트 위 — 사람마다 다른 이스케이프에 맞춰 무게 두는 곳을 바꿔 본다']::text[], array['closed-guard','half-guard','mount']::text[], array['hip-bump-sweep','knee-shield-half-guard']::text[], array['training-intensity','investing-in-loss','positional-sparring']::text[], 44) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('investing-in-loss', '지면서 배우기', 'Investing in Loss', 'learning', '진 장면 하나를 골라 그 바로 앞부터 다시 연습해 배우는 것', array['롤링에서 진 판 전체가 아니라, 무너진 순간 하나를 골라 다시 만들어 보는 연습법','그냥 지고 넘어가면 다음 판도 같은 자리에서 같은 식으로 진다','완전히 잡힌 뒤가 아니라 그 한두 동작 앞(그립을 준 순간 · 프레임을 놓친 순간)에서 다시 시작한다','한 번에 하나만 바꿔서 해 보고, 프레임 하나 지킨 것도 나아진 걸로 센다','서브미션이 들어오면 참지 말고 탭하고, 그 직전부터 다시 해 본다','흔한 오해: 많이 깨지고 버티면 저절로 는다 — 원인을 이름 붙여야 는다']::text[], array['사이드 컨트롤 아래 — 상대 가슴이 붙기 직전부터 시작해 팔꿈치를 안으로 넣고 무릎을 되찾는다','백 컨트롤 아래 — 상대 팔이 목에 들어온 순간을 찾아 그 전에 손 싸움부터 다시 한다','오픈 가드 — 계속 패스당하면 그립을 먼저 잡았는지, 다리를 먼저 잡혔는지만 비교한다']::text[], array['side-control','back-control','open-guard']::text[], array['side-control-escape','hand-fighting-from-back']::text[], array['defend-with-purpose','positional-sparring','prevention-over-cure']::text[], 45) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('attack-with-fallback', '돌아올 곳이 있는 공격', 'Committed Techniques', 'learning', '공격이 막혔을 때 돌아갈 자리까지 정해 두고 들어가는 것', array['공격 하나를 들어가기 · 막혔을 때 · 돌아오기까지 한 묶음으로 익히는 것','막혔을 때 갈 곳이 없으면 좋은 자리에서 공격하다가 오히려 아래로 깔린다','공격 중에도 놓치면 안 되는 연결(팔꿈치 잡은 손 · 가슴과 등 붙임)이 뭔지 먼저 안다','"이 연결이 풀리면 공격을 접는다"는 신호를 하나 정하고, 그때 바로 원래 자리로 돌아온다','막혀도 아직 핵심 연결이 살아 있으면 너무 빨리 포기하지 않는다','흔한 실수: 연결이 이미 풀렸는데 습관처럼 다리를 끝까지 넘겨서 자리를 잃는다']::text[], array['마운트 — 암바 중 팔꿈치가 빠지면 다리 넘기기를 멈추고 다시 마운트로 눌러 앉는다','백 컨트롤 — 초크가 안 들어가고 상대 어깨가 매트로 내려가면 공격보다 시트벨트부터 되찾는다','클로즈드 가드 — 스윕이 막히면 다리와 그립을 바로 되돌려 가드를 다시 닫는다']::text[], array['mount','back-control','closed-guard']::text[], array['mount-armbar','rear-naked-choke','back-control-maintain','mount-maintain']::text[], array['position-before-submission','submission-chain','predictable-responses']::text[], 46) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('prevention-over-cure', '미리 막기', 'Prevention Over Cure', 'learning', '완전히 잡히고 나서 빠지기보다 잡히기 직전에 막는 게 훨씬 쉽다', array['상대가 다음 단계로 가는 데 꼭 필요한 그립 · 각도 · 연결을 먼저 막는 것','눌린 뒤 빠지려면 힘이 몇 배 들고, 이미 공간이 없어서 쓸 수 있는 방법도 줄어든다','내가 확실히 알아챌 수 있는 첫 신호(무릎이 치워짐 · 손이 깃으로 들어옴)를 하나씩 익힌다','모든 손길을 다 막지 말고, 상대가 그걸로 뭘 하려는지 보고 더 급한 것부터 막는다','이미 자리가 굳었으면 미리 막기를 고집하지 말고 그 자리에 맞는 이스케이프로 바꾼다','흔한 실수: 늘 완전히 눌린 상태에서만 이스케이프를 연습해서 그 앞의 선택을 못 배운다']::text[], array['하프가드 아래 — 니 쉴드가 치워졌지만 가슴이 아직 안 붙었을 때 다리를 다시 넣는다','클로즈드 가드 위 — 상대 손이 내 깃으로 들어오면 내 공격보다 그 그립부터 끊는다','패스 싸움 — 상대가 뒤로 돌아가기 시작하면 백이 잡히기 전에 몸을 돌려 마주 본다']::text[], array['half-guard','side-control','back-control']::text[], array['knee-shield-retention','half-guard-recovery','turn-into-opponent']::text[], array['timing-windows','defend-with-purpose','guard-retention']::text[], 47) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('predictable-responses', '상대 반응 보고 다음 수', 'Predictable Responses', 'learning', '예상한 반응이 아니라 상대가 실제로 한 반응을 보고 다음 기술을 고르는 것', array['첫 공격에 상대가 손을 짚거나 무게를 뒤로 빼는 등 눈에 보이는 변화를 읽고 이어 가는 것','"이렇게 하면 저렇게 하겠지"만 믿고 외운 다음 기술을 쓰면 없는 빈틈을 쫓게 된다','반응을 손이 짚었다 · 무게가 뒤로 갔다 · 무릎이 안으로 들어왔다처럼 몸 변화로 본다','상대가 첫 공격을 못 막았으면 바꾸지 말고 그대로 끝낸다','기대한 신호가 안 나오면 억지로 다음 기술을 쓰지 말고 자리를 지키며 다시 만든다','흔한 오해: 밀면 반드시 밀어낸다 — 물러나거나 반격하는 사람도 많다']::text[], array['클로즈드 가드 — 당겼는데 상대가 몸을 세우며 뒤로 앉으면 일어나 앉아 힙 범프 스윕을 노린다','버터플라이 가드 — 스윕에 상대 손이 매트를 짚으면 그 손이 아직 거기 있을 때 다음 공격을 고른다','패스 — 가드 쪽 무릎이 내 패스 방향으로 돌아오면 엉덩이가 따라오는지 보고 방향을 바꾼다']::text[], array['closed-guard','butterfly-guard','passing']::text[], array['hip-bump-sweep','kimura-sweep','butterfly-sweep']::text[], array['action-reaction','timing-windows','submission-chain']::text[], 48) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('timing-windows', '타이밍 창', 'Timing Windows', 'learning', '상대 무게 · 접촉이 잠깐 바뀌어 내 기술이 될 때가 열리는 짧은 순간', array['상대 균형 · 지지하는 손발 · 무게가 잠깐 바뀌어 특정 동작이 가능해지는 틈','이 틈을 모르면 아무 때나 힘을 써서 지치거나, 틈이 닫힌 뒤에 들어가 실패한다','기술 하나에 신호 하나를 짝지어 익힌다 — 예) 무게가 훅에 실리면 버터플라이 스윕','신호를 기다리기 전에 그 기술에 필요한 그립 · 자세를 먼저 갖춰 둔다','오래 기다리기만 하면 상대가 자리를 굳히니, 살짝 흔들어서 신호를 직접 만든다','흔한 실수: 상대가 움직이기만 하면 틈이라고 착각한다 — 내가 막혔던 게 풀려야 틈이다']::text[], array['마운트 아래 — 상대가 손을 고치느라 무게가 뜰 때 팔꿈치와 무릎을 붙여 다리를 되찾는다','버터플라이 가드 — 상대 무게가 훅 위에 실린 순간에만 스윕을 건다','패스 — 가드 바꾸느라 상대 발 하나가 떨어진 순간 반대 다리가 막기 전에 지나간다']::text[], array['mount','butterfly-guard','passing']::text[], array['mount-escape-elbow','butterfly-sweep','mount-escape-upa']::text[], array['kuzushi','predictable-responses','prevention-over-cure']::text[], 49) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('energy-conservation', '힘 아끼기', 'Energy Conservation', 'learning', '쓸데없는 힘은 빼고, 자리를 좋게 하거나 급한 위험을 막는 데만 힘을 쓰는 것', array['몸에 들어간 쓸데없는 힘을 빼고, 꼭 필요한 순간에만 힘을 쓰는 습관','처음부터 꽉 쥐고 버티면 몇 분 만에 숨이 차고, 정작 기회가 와도 움직일 힘이 없다','근육으로 버티기 전에 뼈로 만든 프레임과 무게 두는 곳으로 먼저 버틴다','숨을 참지 말고 계속 쉰다 — 눌릴수록 길게 내쉰다','큰 동작은 틈을 만든 뒤에 한 번에 쓴다 — 같은 브릿지를 열 번 반복하지 않는다','흔한 오해: 힘 아끼기 = 가만히 쉬기 — 위험한 자리에서 쉬면 그대로 끝난다']::text[], array['사이드 컨트롤 아래 — 팔로 밀어내지 말고 오른쪽 팔뚝 프레임을 세워 무게를 뼈로 받는다','마운트 아래 — 아무 때나 브릿지하지 말고 프레임으로 준비한 뒤 한 번에 크게 쓴다','클로즈드 가드 — 다리를 계속 꽉 조이지 말고 상대가 일어설 때만 조인다']::text[], array['side-control','mount','closed-guard','back-control']::text[], array['side-control-escape','mount-escape-upa']::text[], array['frames','flow-rolling','smaller-circles']::text[], 50) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('smaller-circles', '동작을 작게 다듬기', 'Making Smaller Circles', 'learning', '기술 하나에서 필요 없는 동작을 빼며 작고 정확하게 다듬어 가는 연습법', array['이미 아는 기술 하나를 골라, 꼭 필요한 동작만 남을 때까지 다듬는 연습법','이것저것 새로 배우기만 하면 다 어설퍼서 실제 롤링에서는 아무것도 안 걸린다','그 기술에서 빠지면 안 되는 핵심(엉덩이 들기 · 각도 · 균형 무너뜨리기)을 먼저 구분한다','한 번에 하나씩 군더더기(괜한 그립 고치기 · 미리 티 나는 몸짓)를 빼고, 상대가 버텨도 되는지 확인한다','핵심이 생각 없이 나올 만큼 익으면 그때 비슷한 변형을 하나씩 붙인다','흔한 실수: 협조하는 상대에게만 되는데 다 익었다고 믿고 너무 빨리 넓힌다']::text[], array['클로즈드 가드 — 힙 범프 스윕을 다듬다 보면 같은 엉덩이 들기를 쓰는 기무라도 같이 좋아진다','하프가드 아래 — 언더훅 잡고 올라오는 동작 하나만 몇 주 동안 버티는 상대에게 시험한다','사이드 컨트롤 아래 — 프레임 · 쉬림프에서 괜히 크게 움직이는 부분을 줄인다']::text[], array['closed-guard','half-guard','side-control']::text[], array['hip-bump-sweep','kimura-guard','half-guard-underhook']::text[], array['double-down','positional-sparring','energy-conservation']::text[], 51) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('double-down', '잘하는 것 파기', 'Double Down on Strengths', 'learning', '잘 되는 자리 하나를 골라 들어가는 길 · 막혔을 때 답까지 깊게 파는 것', array['이미 롤링에서 자주 통하는 자리와 공격 하나를 골라 집중해서 키우는 것','좋아하는 기술이 완벽한 그립에서만 되면, 실제로는 그 자리에 가지도 못하고 끝난다','공격만이 아니라 그 자리로 들어가는 길도 같이 연습한다 — 그립을 미리 주고 시작하지 않는다','상대가 가장 자주 하는 막기 하나와 그때 갈 다른 길 하나를 같이 준비한다','잘하는 것만 하지 말고 이스케이프와 낯선 자리도 계속 연습한다','흔한 오해: 체형이 이러니 이 게임 — 체형보다 실제로 해 보니 되는지로 고른다']::text[], array['하프가드 아래 — 스윕은 되는데 언더훅을 못 잡으면, 언더훅을 뺏긴 상태부터 시작해 연습한다','마운트 — 서브미션 전에 패스에서 마운트로 넘어가며 균형 잡고 앉는 것부터 다듬는다','패스 — 주로 쓰는 패스 하나와, 막혔을 때 갈 다른 패스 하나만 정해 둔다']::text[], array['half-guard','mount','passing']::text[], array['half-guard-underhook','old-school-sweep','consolidate-mount']::text[], array['smaller-circles','investing-in-loss','attack-with-fallback']::text[], 52) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('defend-with-purpose', '목적 있는 방어', 'Defend With Purpose', 'learning', '막기만 하지 말고, 막으면서 다음에 갈 작은 목표를 정해 두는 방어', array['급한 위험을 먼저 막고, 그다음 갈 수 있는 작은 한 걸음을 정해 두는 방어','목표 없이 버티기만 하면 상대가 누르기를 바꿀 시간만 벌어 주고 결국 더 깊이 잡힌다','순서: 목 · 팔 같은 서브미션 위험 먼저 → 팔꿈치 안으로 → 엉덩이 빼기 → 무릎 · 다리 되찾기','프레임으로 생긴 공간에는 바로 엉덩이를 넣는다 — 안 쓰면 공간은 금방 닫힌다','한 번에 끝까지 빠지려 하지 말고, 얻은 것(하프가드 · 안쪽 팔꿈치)을 먼저 지킨다','흔한 실수: 이미 걸린 서브미션 속에서 자리부터 빠지려다 더 조여진다 — 못 막으면 탭']::text[], array['사이드 컨트롤 아래 — 첫 목표는 오른쪽 팔꿈치를 안으로 넣기, 그다음 무릎을 사이에 넣기','마운트 아래 — 목을 지키고 브릿지로 상대 균형을 흔든 뒤 하프가드로 다리 하나를 되찾는다','하프가드 아래 — 납작하게 눌려도 잡은 다리는 놓지 말고 프레임과 옆으로 눕기부터 다시 만든다']::text[], array['side-control','mount','half-guard','back-control']::text[], array['side-control-escape','mount-escape-elbow','half-guard-recovery','back-escape']::text[], array['escape-basics','defense-under-pressure','submission-defense']::text[], 53) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
insert into public.concepts (slug, name_ko, name_en, kind, summary, body, examples, related_positions, related_techniques, see_also, sort_order) values ('competition-basics', '첫 시합 준비', 'First Competition Basics', 'learning', '첫 시합은 규정 확인 · 쓸 기술 몇 개 · 긴장 다루기만 준비해도 충분하다', array['첫 시합은 이기는 것보다 긴장 속에서 연습한 걸 꺼내 쓰는 경험을 쌓는 자리','준비 없이 나가면 긴장으로 숨이 먼저 차고, 몰랐던 규정 때문에 점수 · 실격으로 지기 쉽다','체육관 · 대회 규정을 확인한다 — 체급 · 계체 시간, 경기 시간, 점수, 띠별로 금지된 기술','시작(테이크다운이냐 가드 풀링이냐) 하나, 주로 갈 길 하나, 막혔을 때 다른 길 하나만 정한다','시합 몇 주 전부터 코치와 경기 시간 · 규정에 맞춘 롤링을 몇 번 해 본다','경기 중엔 다음 동작 하나만 생각하고, 끝나면 결과보다 선택을 돌아본다','흔한 실수: 시합 직전에 새 기술을 배워서 넣으려 한다 — 이미 되는 것만 쓴다']::text[], array['스탠딩 · 클린치 — 테이크다운이 자신 없으면 미리 정한 가드 풀링으로 바로 시작한다','클로즈드 가드 — 시합 첫 자리로 정해 두고, 스윕 하나와 서브미션 하나만 준비한다','마운트 · 백 — 서브미션이 막혀도 자리를 놓치지 않는 것을 우선한다']::text[], array['standing','clinch','closed-guard']::text[], array['pulling-guard','double-leg-takedown','breakfall']::text[], array['training-intensity','double-down','tap-safety']::text[], 54) on conflict (slug) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, kind = excluded.kind, summary = excluded.summary, body = excluded.body, examples = excluded.examples, related_positions = excluded.related_positions, related_techniques = excluded.related_techniques, see_also = excluded.see_also, sort_order = excluded.sort_order;
