-- 기술 지도 2 (D-83): 포지션 설명 · 위/아래 노트 · 원칙/개념 카드. 온라인 MCP 용 공용 콘텐츠 — 누구나 읽기, 쓰기는 마이그레이션으로만.

alter table public.positions
  add column if not exists summary text,
  add column if not exists variants text[] not null default '{}';

-- 포지션마다 위 · 아래(또는 서서) 노트 하나씩
create table if not exists public.position_notes (
  id uuid primary key default gen_random_uuid(),
  position_id uuid not null references public.positions(id) on delete cascade,
  role text not null check (role in ('top', 'bottom', 'standing')),
  goals text[] not null default '{}',
  keys text[] not null default '{}',
  decisions text[] not null default '{}',
  mistakes text[] not null default '{}',
  drills text[] not null default '{}',
  created_at timestamptz not null default now(),
  unique (position_id, role)
);
alter table public.position_notes enable row level security;
create policy "position_notes: 누구나 보기" on public.position_notes for select using (true);

-- 원칙(principle) · 공부법(learning) 카드
create table if not exists public.concepts (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name_ko text not null,
  name_en text not null,
  kind text not null check (kind in ('principle', 'learning')),
  summary text not null,
  body text[] not null default '{}',
  examples text[] not null default '{}',
  related_positions text[] not null default '{}',
  related_techniques text[] not null default '{}',
  see_also text[] not null default '{}',
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);
alter table public.concepts enable row level security;
create policy "concepts: 누구나 보기" on public.concepts for select using (true);

-- 내용 채우기: 포지션 21개 설명 · 노트, 개념 카드 55개
update public.positions set summary = '둘 다 선 상태 — 그립과 거리를 먼저 잡은 쪽이 넘기거나 막는다', variants = array['레슬링 스탠스 — 그립 없이 낮게 서서 다리를 노린다','유도 그립 — 깃 · 소매를 잡고 던지기를 노린다','스퀘어 스탠스 — 두 발이 나란해 앞뒤로 약하다']::text[] where slug = 'standing';
update public.positions set summary = '서서 몸이 붙은 상태 — 언더훅 · 칼라 타이 싸움 또는 가드로 내려가기', variants = array['언더훅 클린치 — 내 오른팔을 상대 왼팔 밑에 넣고 붙는다','칼라 타이 — 내 오른손으로 상대 목 뒤를 잡는다','러시안 타이 — 두 손으로 상대 팔 하나를 감싼다','바디락 — 두 팔로 상대 허리를 감는다','스탠딩 백 — 상대 뒤에 붙은 상태']::text[] where slug = 'clinch';
update public.positions set summary = '아래가 두 다리로 위의 허리를 잠근 가드 — 아래가 공격권을 가진다', variants = array['하이 가드 — 다리를 상대 겨드랑이 쪽으로 올려 팔을 묶는다','오버훅(클램프) 가드 — 내 왼팔로 상대 오른팔을 감아 묶는다','스탠딩 클로즈드 가드 — 상대가 일어선 채 다리가 잠겨 있다']::text[] where slug = 'closed-guard';
update public.positions set summary = '아래가 다리를 풀고 발 · 정강이로 거리를 막는 가드 — 거리 싸움', variants = array['시팅 가드 — 앉아서 내 오른손을 뒤에 짚고 상대를 마주 본다','발 골반 가드 — 두 발을 상대 골반에 대 거리를 만든다','신 투 신 가드 — 내 정강이를 상대 앞 정강이 안쪽에 댄다','케이 가드 — 정강이를 상대 허벅지 안쪽에 넣어 다리를 노린다']::text[] where slug = 'open-guard';
update public.positions set summary = '앉아서 두 발 훅을 상대 허벅지 안에 넣는 가드 — 들어 올려 넘기기', variants = array['버터플라이 하프 — 한쪽은 하프로 감고 한 발만 훅','싱글 버터플라이 — 한 발 훅, 다른 다리로 거리 조절','버터플라이 → X 가드 — 상대를 들어 올린 뒤 X 가드로 들어간다']::text[] where slug = 'butterfly-guard';
update public.positions set summary = '발로 상대 앞다리를 바깥에서 감는 가드 — 흔들어 넘기거나 뒤로 돈다', variants = array['데라히바 — 내 왼다리로 상대 오른다리를 바깥에서 감는다','리버스 데라히바 — 내 오른다리로 상대 오른다리를 안쪽에서 감는다','베림볼로 — 데라히바에서 뒤집어 상대 등으로 돈다','데라히바 → X 가드 — 상대 다리 밑으로 들어가 X 가드로']::text[] where slug = 'de-la-riva';
update public.positions set summary = '아래가 양 소매를 잡고 발로 팔을 밀어 거리를 쥔 오픈 가드, 위는 그립부터 끊어야 한다', variants = array['스파이더 — 양 소매를 잡고 내 왼발은 상대 오른쪽 이두, 오른발은 상대 왼쪽 이두를 민다','라쏘 — 내 왼다리로 상대 오른팔을 바깥에서 감고 내 왼손으로 그 소매를 잡는다','칼라 슬리브 — 내 오른손 상대 왼쪽 깃, 왼손 상대 오른쪽 소매, 왼발 상대 오른쪽 이두','더블 슬리브 — 양손으로 양 소매만 잡고 발은 골반·이두를 오가며 쓴다']::text[] where slug = 'spider-lasso';
update public.positions set summary = '아래가 상대 라펠을 상대 다리에 감아 묶는 도복 가드, 위는 라펠부터 풀어야 한다', variants = array['라펠 가드 — 상대 오른쪽 라펠을 꺼내 상대 오른다리 오금 뒤로 돌려 내 왼손으로 잡는다','웜 가드 — 돌린 라펠을 내 왼다리에 감고 왼발은 상대 오른쪽 골반, 라펠 끝은 내 오른손','라펠 + 데라히바 — 라펠을 잡은 채 내 왼다리로 상대 오른다리에 데라히바 훅','라펠 + 라쏘 · 스파이더 — 라펠 그립에 내 왼발로 상대 오른팔을 막아 묶는다']::text[] where slug = 'lapel-guard';
update public.positions set summary = '아래가 서 있는 상대 다리 밑에서 양다리로 한 다리를 묶어 띄우는 가드', variants = array['X 가드 — 상대 왼다리를 내 오른쪽 어깨에 안고, 내 왼발은 상대 오른쪽 오금, 오른발은 상대 오른쪽 허벅지','싱글 레그 X — 상대 왼쪽 발목을 내 오른쪽 겨드랑이에 안고 내 오른발은 상대 왼쪽 골반','리버스 X — 상대 오른다리를 내 왼쪽 어깨에 안고 내 오른다리로 상대 왼쪽 오금을 건다','스트레이트 앵클락 — 싱글 레그 X에서 상대 왼발을 내 오른팔로 감아 내 오른쪽으로 눕는다']::text[] where slug = 'x-guard';
update public.positions set summary = '아래가 상대 오른다리 한쪽만 감은 자세, 언더훅과 크로스페이스 싸움이 승부를 가른다', variants = array['니 쉴드 — 내 왼쪽 무릎·정강이를 상대 배 앞에 가로로 세워 거리를 만든다','Z 가드 — 니 쉴드와 같은 그림으로 왼쪽 정강이를 높게 세워 상대 상체를 막는다','언더훅 하프 — 내 왼팔로 상대 오른쪽 겨드랑이 밑을 파고 옆으로 일어나 앉는다','쿼터 가드 — 상대 오른쪽 발목만 겨우 걸린, 패스 직전의 얕은 하프가드','도그파이트 — 언더훅으로 무릎까지 올라와 상대와 옆으로 맞붙은 자세','눌린 하프 — 등이 바닥에 붙고 상대 크로스페이스에 눌린 위험한 상태']::text[] where slug = 'half-guard';
update public.positions set summary = '아래가 상대 엉덩이 밑으로 깊이 들어가 오른다리를 안은 자세, 위가 불리하기 쉽다', variants = array['딥 하프 — 내 오른팔로 상대 오른쪽 허벅지를 안고 내 머리는 상대 다리 사이 밑에 둔다','웨이터 — 상대 왼쪽 발목을 내 왼손으로 들어 쟁반 들듯 넘긴다','호머 심슨 — 상대 쪽으로 엉덩이를 돌려 바닥을 보며 굴러 넘긴다']::text[] where slug = 'deep-half';
update public.positions set summary = '위는 다리를 지나 사이드로 가려 하고, 아래는 가드를 지키는 싸움', variants = array['토레안도 — 상대 양 무릎을 잡고 다리를 옆으로 치우며 돌아 들어간다','니슬라이스 — 무릎을 상대 허벅지 위로 미끄러뜨려 지나간다','레그 드래그 — 상대 다리를 내 허리 옆으로 끌어 엉덩이를 돌려놓는다','스택 (더블 언더) — 상대 다리를 양팔로 감아 접고 무게로 누르며 지나간다','바디락 — 상대 허리를 양팔로 감고 가슴을 붙인 채 다리를 빼낸다','헤드쿼터 — 한쪽 무릎을 상대 다리 사이에 넣고 자리 잡는 중간 지점']::text[] where slug = 'passing';
update public.positions set summary = '위가 옆에서 가슴을 붙여 누르는 자리 — 위가 크게 유리', variants = array['크로스페이스 사이드 — 왼팔로 상대 얼굴을 상대 왼쪽으로 돌려 누르는 기본형','언더훅 사이드 — 왼팔을 상대 왼 겨드랑이 아래로 넣어 상체를 묶는다','기프트 랩 — 상대 오른팔을 상대 목 앞으로 감아 내 손에 넘긴다','숄더 오브 저스티스 — 어깨로 상대 턱을 눌러 고개를 못 돌리게 한다']::text[] where slug = 'side-control';
update public.positions set summary = '위가 상대 머리 쪽에서 가슴을 맞대고 누르는 자리 — 위가 유리', variants = array['남북 초크 자세 — 팔로 상대 목을 감고 옆구리로 조른다','기무라 남북 — 상대 팔을 기무라 그립으로 잡고 머리 쪽에서 돌린다']::text[] where slug = 'north-south';
update public.positions set summary = '위가 무릎으로 배를 누르며 움직이는 자리 — 위가 유리하지만 덜 안정', variants = array['니 온 밸리 기본 — 오른 무릎 배 위, 왼다리는 펴서 버팀','리버스 니 온 밸리 — 상대 다리 쪽을 보고 무릎을 올린다']::text[] where slug = 'knee-on-belly';
update public.positions set summary = '위가 옆에 앉아 목과 팔을 감아 누르는 유도식 누르기 — 위가 유리', variants = array['곁누르기 (혼 케사) — 오른팔로 목 뒤를 감고 상대 오른팔을 왼 겨드랑이에 낀다','변형 곁누르기 (쿠즈레 케사) — 목 대신 상대 왼 겨드랑이에 언더훅','리버스 곁누르기 — 상대 발 쪽을 보고 앉아 상대 오른팔을 오른 겨드랑이에 낀다']::text[] where slug = 'kesa-gatame';
update public.positions set summary = '상대 배 위에 올라탄 자세 — 위가 크게 유리, 아래는 탈출이 먼저', variants = array['로우 마운트 — 엉덩이를 상대 명치에 낮게 두고 무게로 누르는 기본 자세','하이 마운트 — 무릎을 상대 겨드랑이까지 올려 팔과 목을 노린다','S 마운트 — 내 왼 무릎을 상대 머리 오른쪽에 두고 상대 오른팔 암바를 노린다','테크니컬 마운트 — 상대가 내 오른쪽으로 돌아누우면 오른 무릎을 등 뒤에 두고 따라간다','3/4 마운트 — 아래 사람이 내 왼다리를 감아 하프가드 직전인 상태','마운티드 크루시픽스 — 상대 오른팔은 내 왼 무릎, 왼팔은 내 오른팔로 가둔다']::text[] where slug = 'mount';
update public.positions set summary = '상대 등 뒤에 붙어 훅과 시트벨트로 잡은 자세 — 위가 가장 유리', variants = array['시트벨트 — 내 오른팔은 상대 오른 어깨 위, 왼팔은 왼 겨드랑이 밑으로 두 손을 잡는다','투 훅 — 두 발등을 상대 허벅지 안쪽에 걸어 엉덩이를 묶는다','바디 트라이앵글 — 내 왼다리를 배 앞에 두르고 왼 발목을 오른 무릎 뒤에 잠근다','훅 없는 시트벨트 — 다리가 걸리기 전, 상체만 붙잡은 상태']::text[] where slug = 'back-control';
update public.positions set summary = '아래가 무릎·팔꿈치를 붙여 웅크린 자세 — 위는 백, 아래는 가드 회복', variants = array['터틀 — 무릎과 팔꿈치를 붙여 웅크리고 목과 옆구리를 막는 자세','크루시픽스 — 위가 상대 왼팔은 다리로, 오른팔은 왼손으로 가둬 두 팔을 묶는다','크랩 라이드 — 상대 등 뒤 정면에서 두 발을 훅으로 걸고 띠를 잡는다','로데오 라이드 — 상대 등에 올라타 다리로 엉덩이를 묶는 자세']::text[] where slug = 'turtle';
update public.positions set summary = '숙인 상대의 머리를 내 가슴 밑에 끼운 자세 — 위가 초크와 백을 노림', variants = array['프론트 헤드락 — 내 오른팔로 턱 밑을 감고 왼손으로 상대 오른쪽 삼두를 잡는다','길로틴 — 감은 팔로 목을 조이는 기술, 하이 엘보·암 인·텐 핑거 등','다스 · 아나콘다 — 내 오른팔을 꿰어 상대 왼팔과 목을 같이 감아 조인다','넥타이 — 페루비안·재패니즈, 목을 감은 뒤 다리나 몸무게로 조인다']::text[] where slug = 'front-headlock';
update public.positions set summary = '관절기·초크가 이미 걸린 순간 — 공격자는 끝내고 방어자는 빠진다', variants = array['암바 — 상대 오른팔을 다리 사이에 끼우고 엉덩이를 들어 팔꿈치를 편다','벨리 다운 암바 — 상대가 돌아 엎드리면 따라 엎드려 마무리한다','트라이앵글 — 내 오른다리로 목 뒤, 왼 오금으로 잠가 목과 오른팔을 같이 조인다','기무라 — 8자 그립으로 상대 오른팔을 등 쪽으로 돌린다','오모플라타 — 내 왼다리로 상대 오른 어깨를 눌러 어깨를 꺾는다','고고플라타 — 내 왼 정강이를 상대 목 앞에 대고 누른다']::text[] where slug = 'submission-control';
